insert into gather_def values ('hod', 'masonry', 'hod carrying', 'carry what planned building work wants from your settlement stores and fit it: walls on any storey, floors, roofs, staircases, ladders, columns, bridge or aqueduct spans, foundations');
insert into gather_def values ('mend', 'repair', 'mending', 'mend damaged gear in your settlement stores');
insert into gather_def values ('compost', 'farming', 'composting', 'turn rotting items into compost');
insert into gather_def values ('seek', 'archaeology', 'seeking relics', 'find buried relics and mark dig sites');
insert into gather_def values ('fish', 'fishing', 'fishing', 'fish round the settlement and bring the catch home');
insert into gather_def values ('prune', 'forestry', 'pruning', 'prune dying wood');
insert into gather_def values ('stump', 'digging', 'digging out stumps', 'dig out stumps');
insert into gather_def values ('fruit', 'forestry', 'picking fruit', 'pick fruit trees');
insert into gather_def values ('hive', 'animal_husbandry', 'tending hives', 'tend the hives');
insert into gather_def values ('groom', 'animal_husbandry', 'grooming', 'brush your wildermon under 40% care');
insert into gather_def values ('dairy', 'animal_husbandry', 'milking and shearing', 'milk your cudda into empty buckets in your settlement stores; shear or pluck your others at 90% regrowth; output to your settlement stores');
insert into gather_def values ('heal', 'first_aid', 'healing', 'dress your wildermon that are bleeding or under 75% health, with a bandage or cover from your settlement stores');
insert into gather_def values ('butcher', 'butchering', 'butchering', 'butcher carcasses in your settlement stores; output to your settlement stores');
insert into gather_def values ('tan', 'leatherworking', 'tanning hides', 'tan hides in your settlement stores with lye; needs a carving knife in your settlement stores');
insert into gather_def values ('mill', 'milling', 'milling', 'grind wheat and corn and press olives in your settlement stores; needs a quern in your settlement stores');
insert into gather_def values ('lamp', 'carrying', 'lamplighting', 'put candles from your settlement stores in your empty lantern posts and pillars; light them after dark, put them out by day');
insert into gather_def values ('bush', 'forestry', 'picking bushes and vines', 'pick bushes and trellis vines');
insert into gather_def values ('grass', 'foraging', 'cutting grass and moss', 'cut grass and moss');
insert into gather_def values ('pan', 'prospecting', 'panning', 'pan sand at the water''s edge');
insert into gather_def values ('smelt', 'smelting', 'charging smelters', 'charge your smelters with ore from your settlement stores and empty them');
insert into gather_def values ('kiln', 'pottery', 'loading kilns', 'load your kilns with unfired pottery from your settlement stores and empty them');
insert into gather_def values ('ash', 'alchemy', 'raking ashes', 'rake ashes from your campfires, ovens, smelters and kilns into your settlement stores; leach ash and buckets of water from your settlement stores into lye');
insert into gather_def values ('brew', 'brewing', 'brewing', 'start a brew in each idle water barrel of yours from makings in your settlement stores');
insert into gather_def values ('cook', 'cooking', 'cooking', 'cook from your settlement stores at your lit campfires and ovens');
insert into gather_def values ('restore', 'restoration', 'restoring', 'restore relics whose pieces are all in your settlement stores');
insert into gather_def values ('patch', 'farming', 'tending planters', 'sow, tend and harvest your planters from your settlement stores');
insert into gather_def values ('worm', 'digging', 'digging worms', 'dig worms');
insert into gather_def values ('sprout', 'forestry', 'picking sprouts', 'pick tree sprouts');
insert into gather_def values ('resin', 'forestry', 'tapping pines', 'tap pines for tar, once a day each');
insert into gather_def values ('flower', 'foraging', 'picking wildflowers', 'pick wildflowers, except those a skep feeds on');
insert into gather_def values ('scrub', 'masonry', 'scrubbing stone', 'scrub moss off your paving, foundations and statues and ivy off your stone walls');
insert into gather_def values ('saw', 'carpentry', 'sawing planks', 'saw logs in your settlement stores into planks, 3 a log; needs a saw in your settlement stores');
insert into gather_def values ('chisel', 'stonecutting', 'chiselling stone brick', 'chisel rock shards in your settlement stores into stone brick, 2 a shard; needs a chisel in your settlement stores');
insert into gather_def values ('brick', 'pottery', 'shaping clay brick', 'shape clay in your settlement stores into unfired clay brick, 1 a lump');
insert into gather_def values ('rope', 'ropemaking', 'making rope', 'make rope from wemp in your settlement stores, 4 fibres a rope; needs a rope tool in your settlement stores');
insert into gather_def values ('fletch', 'fletching', 'fletching arrows', 'fletch arrows from shafts, arrowheads and feathers in your settlement stores, 3 a shaft, 3 heads and 3 feathers; needs a carving knife in your settlement stores');
insert into gather_def values ('paper', 'papyrusmaking', 'pressing papyrus', 'press reeds in your settlement stores into papyrus at your paper presses, 3 sheets per 4 reeds and 3 L water from your settlement stores');
insert into gather_def values ('glaze', 'pottery', 'glazing pottery', 'glaze fired pots, bowls, jars and amphorae in your settlement stores with 1 ash each from your settlement stores; glazed pottery never decays');
