insert into class_perk values ('terraformer_quick_level', 'terraformer', 1, 10, 'Quick Level', 'Flatten time −35% (base 3.5 s).', '{"time:flatten":0.65}');
insert into class_perk values ('terraformer_bed_worker', 'terraformer', 1, 17, 'Bed Worker', 'Collect time −30% (base 7 s).', '{"time:collect":0.7}');
insert into class_perk values ('terraformer_quick_paver', 'terraformer', 1, 25, 'Quick Paver', 'Pack, Pave (cobblestone) and Pave (slabs) time −35%.', '{"time:pack":0.65,"time:pave_cobble":0.65,"time:pave_slabs":0.65}');
insert into class_perk values ('terraformer_level_hand', 'terraformer', 2, 9, 'Level Hand', 'Flatten height per action: 0.2 m (base 0.1 m).', '{"flatten:step":2}');
insert into class_perk values ('terraformer_wader', 'terraformer', 2, 14, 'Wader', 'Dig and Flatten max water depth: 2.0 m (base 1.0 m).', '{"depth:dig":20}');
insert into class_perk values ('terraformer_stump_puller', 'terraformer', 2, 23, 'Stump Puller', 'Dig out the stump time −50%. Output: 1 log of the tree''s kind (base: none).', '{"time:dig_stump":0.5,"stump:log":1}');
insert into class_perk values ('terraformer_steep_cut', 'terraformer', 3, 12, 'Steep Cut', 'Max slope left by Dig, Change tile and Dredge: 0.4 m per digging level (base 0.3 m, min 4.0 m).', '{"slope:digging":4}');
insert into class_perk values ('terraformer_dredger', 'terraformer', 3, 15, 'Dredger', 'Dredge max depth: 6.0 m (base 3.0 m). Dredge time −20%.', '{"depth:dredge":60,"time:dredge":0.8}');
insert into class_perk values ('terraformer_bed_true', 'terraformer', 3, 26, 'Bed True', 'Pave (slabs) never fails (base: check at difficulty 10 against the slab''s QL).', '{"fail:pave_slabs":0}');
insert into class_perk values ('terraformer_frugal_cobbler', 'terraformer', 4, 27, 'Frugal Cobbler', 'Pave (cobblestone) uses no stone brick: 1 in 3 actions.', '{"keep:pave_cobble":0.3333333333333333}');
insert into class_perk values ('terraformer_road_legs', 'terraformer', 4, 29, 'Road Legs', 'Walk speed +15% on packed dirt, cobblestone and stone slabs.', '{"walk:road":1.15}');
insert into class_perk values ('terraformer_soil_porter', 'terraformer', 4, 32, 'Soil Porter', 'Dirt, sand and clay weight: 10 kg per unit (base 20 kg).', '{"weight:dirt":0.5,"weight:sand":0.5,"weight:clay":0.5}');
insert into class_perk values ('terraformer_strong_back', 'terraformer', 5, 33, 'Strong Back', 'Carry weight +40 kg (base 120 kg, +5 kg per body strength level).', '{"carry":40}');
insert into class_perk values ('terraformer_long_reach', 'terraformer', 5, 34, 'Long Reach', 'Change tile and Flatten take soil from carts and containers within 5 tiles (base 2.5). Dug material goes into the nearest unlocked cart or wagon within 5 tiles not pulled or driven by another player (base: your pack).', '{"reach:soil":5}');
insert into class_perk values ('terraformer_dig_out_the_tile', 'terraformer', 5, 44, 'Dig Out the Tile', 'New action: Dig out the tile. Lowers all 4 corners by 0.1 m in one action: 16 s base (4 digs: 24 s). Output: 4 of the material.', '{"dig_tile":1}');
insert into class_perk values ('terraformer_clean_earth', 'terraformer', 6, 5, 'Clean Earth', 'QL +10%: dirt, sand, clay, peat and tar from Dig, Dredge, Collect and Flatten.', '{"ql:dig":1.1,"ql:dredge":1.1,"ql:collect":1.1,"ql:flatten":1.1}');
insert into class_perk values ('terraformer_rare_earth', 'terraformer', 6, 6, 'Rare Earth', 'Rare chance on Dig, Dredge and Collect: 1 in 100 (base: none). Rare may become supreme or fantastic at crafting odds.', '{"rare:dig":0.01,"rare:dredge":0.01,"rare:collect":0.01}');
insert into class_perk values ('terraformer_treasure_nose', 'terraformer', 6, 20, 'Treasure Nose', 'Treasure map chance per dig: 1 in 200 (base 1 in 1000).', '{"map:dig":0.005,"map:dig_tile":0.005}');
insert into class_perk values ('miner_ore_sense', 'miner', 1, 7, 'Ore Sense', 'Mine, Chip corner and Mine out the cellar: mining needed per ore −10. Copper, iron and tin at any mining, zinc at 10, lead at 20, silver at 30, gold at 40, adamantine at 50, glimmersteel at 60, mithril at 70 and seryll at 80 (base: copper at 1, iron at 5, tin at 10, zinc at 20, lead at 30, silver at 40, gold at 50, adamantine at 60, glimmersteel at 70, mithril at 80 and seryll at 90).', '{"ore:below":10}');
insert into class_perk values ('miner_coal_hand', 'miner', 1, 8, 'Coal Hand', 'Coal per Mine on a coal seam: 2 (base one).', '{"count:coal":2}');
insert into class_perk values ('miner_chipper', 'miner', 1, 9, 'Chipper', 'Chip corner lowers the corner: 1 in 2 actions (base 1 in 4).', '{"chip:chance":0.5}');
insert into class_perk values ('miner_rock_slide', 'miner', 2, 13, 'Rock Slide', 'Face collapse while mining (1 in 30 actions): +3 of the mined material.', '{"slide:more":3}');
insert into class_perk values ('miner_wet_work', 'miner', 2, 14, 'Wet Work', 'Mine and Chip corner max water depth: 2.0 m (base 1.0 m).', '{"depth:mine":20}');
insert into class_perk values ('miner_far_reader', 'miner', 2, 19, 'Far Reader', 'Prospect range +3 tiles (base 3, one more per 10 prospecting).', '{"further:prospect":3}');
insert into class_perk values ('miner_quick_pick', 'miner', 3, 1, 'Quick Pick', 'Mine time −25% (base 8 s).', '{"time:mine":0.75}');
insert into class_perk values ('miner_rich_seam', 'miner', 3, 2, 'Rich Seam', 'Mine: one extra output on 15% of actions.', '{"more:mine":0.15}');
insert into class_perk values ('miner_keen_trowel', 'miner', 3, 25, 'Keen Trowel', 'Investigate find chance +15 percentage points, max 85% (base 14% + 40% of archaeology + 10% of trowel QL, max 70%).', '{"find:investigate":0.15,"cap:investigate":0.85}');
insert into class_perk values ('miner_sure_swing', 'miner', 4, 3, 'Sure Swing', 'Mine failure chance ×0.5 (base: check at difficulty 12 with the pickaxe''s QL).', '{"fail:mine":0.5}');
insert into class_perk values ('miner_pieces_that_fit', 'miner', 4, 27, 'Pieces that Fit', 'Investigate: 50% of relic pieces found are a missing piece of an unfinished relic you hold.', '{"fit:relic":0.5}');
insert into class_perk values ('miner_ore_cart', 'miner', 4, 35, 'Ore Cart', 'Mine output goes into the nearest unlocked cart or wagon not pulled or driven by another player, or container you built or on your settlement, within 5 tiles (base: your pack).', '{"into:mine":5}');
insert into class_perk values ('miner_face_shaper', 'miner', 5, 11, 'Face Shaper', 'Chip corner drop per success: 0.2 m (base 0.1 m). Never below a level you have taken.', '{"chip:step":2}');
insert into class_perk values ('miner_gem_eye', 'miner', 5, 15, 'Gem Eye', 'Gem chance per Mine: 1 in 150 (base 1 in 400).', '{"gem:mine":0.006666666666666667}');
insert into class_perk values ('miner_bauble_hunter', 'miner', 5, 28, 'Bauble Hunter', 'Investigate finds that are tarnished baubles: 40% (base 30%).', '{"share:bauble":0.4}');
insert into class_perk values ('miner_rare_ore', 'miner', 6, 6, 'Rare Ore', 'Rare chance on Mine: 1 in 100 (base: none). Rare may become supreme or fantastic at crafting odds.', '{"rare:mine":0.01}');
insert into class_perk values ('miner_treasure_in_the_rock', 'miner', 6, 17, 'Treasure in the Rock', 'Treasure map chance per Mine: 1 in 200 (base 1 in 1000).', '{"map:mine":0.005}');
insert into class_perk values ('miner_pan', 'miner', 6, 50, 'Pan', 'New action: Pan, on sand with water at a corner. 1 in 8 actions give copper ore, tin ore or silver ore (equal odds), QL by prospecting.', '{"pan":0.125}');
insert into class_perk values ('mason_quick_chisel', 'mason', 1, 1, 'Quick Chisel', 'Stonecutting time −25%: bricks, whetstones, querns, telestones and slabs (base 6–20 s).', '{"time:make_stone_brick":0.75,"time:make_slate_brick":0.75,"time:make_marble_brick":0.75,"time:make_sandstone_brick":0.75,"time:make_whetstone":0.75,"time:make_quern":0.75,"time:make_telestone":0.75,"time:make_stone_slab":0.75,"time:make_slate_slab":0.75,"time:make_marble_slab":0.75,"time:make_sandstone_slab":0.75}');
insert into class_perk values ('mason_quick_mason', 'mason', 1, 8, 'Quick Mason', 'Build wall and Build floor time −30% on stone, anything but log, plank or timbercraft (base 5 s).', '{"time:build_stone":0.7}');
insert into class_perk values ('mason_concrete_hand', 'mason', 1, 17, 'Concrete Hand', 'Raise the rock with concrete never fails (base: check at difficulty 10; concrete lost on failure).', '{"fail:raise_rock":0}');
insert into class_perk values ('mason_sure_chisel', 'mason', 2, 4, 'Sure Chisel', 'Stonecutting failure chance ×0.5 (base: check at difficulty 10–30).', '{"fail:make_stone_brick":0.5,"fail:make_slate_brick":0.5,"fail:make_marble_brick":0.5,"fail:make_sandstone_brick":0.5,"fail:make_whetstone":0.5,"fail:make_quern":0.5,"fail:make_telestone":0.5,"fail:make_stone_slab":0.5,"fail:make_slate_slab":0.5,"fail:make_marble_slab":0.5,"fail:make_sandstone_slab":0.5}');
insert into class_perk values ('mason_double_lift', 'mason', 2, 18, 'Double Lift', 'Raise the rock with concrete: 0.2 m per concrete (base 0.1 m), where your slope limit and level allow; otherwise 0.1 m.', '{"lift:raise_rock":2}');
insert into class_perk values ('mason_steep_stone', 'mason', 2, 19, 'Steep Stone', 'Max slope left by raising rock: 0.4 m per masonry level (base 0.3 m, min 4.0 m).', '{"slope:masonry":4}');
insert into class_perk values ('mason_good_mix', 'mason', 3, 20, 'Good Mix', 'Mix concrete output: 2 concrete from the same mortar and ashes (base 1).', '{"count:concrete":2}');
insert into class_perk values ('mason_wet_set', 'mason', 3, 22, 'Wet Set', 'Raising rock max water depth: 1.0 m (base: above water only).', '{"depth:raise_rock":10}');
insert into class_perk values ('mason_brick_porter', 'mason', 3, 33, 'Brick Porter', 'Weight ×0.5: bricks and slabs of stone, slate, marble or sandstone. Brick 7.5 kg, slab 9 kg (base 15 and 18).', '{"weight:stone_brick":0.5,"weight:slate_brick":0.5,"weight:marble_brick":0.5,"weight:sandstone_brick":0.5,"weight:stone_slab":0.5,"weight:slate_slab":0.5,"weight:marble_slab":0.5,"weight:sandstone_slab":0.5}');
insert into class_perk values ('mason_three_from_a_shard', 'mason', 4, 2, 'Three from a Shard', 'Bricks per action, stone, slate, marble or sandstone: 3 (base 2).', '{"count:stone_brick":3,"count:slate_brick":3,"count:marble_brick":3,"count:sandstone_brick":3}');
insert into class_perk values ('mason_two_at_a_time', 'mason', 4, 9, 'Two at a Time', 'Build wall and Build floor units per action on stone, anything but log, plank or timbercraft: 2 if carried (base one; stone-brick wall: 24 stone bricks and 12 mortar).', '{"lay:build_stone":2}');
insert into class_perk values ('mason_bridge_mason', 'mason', 4, 29, 'Bridge Mason', 'Stone arch work time −30% (base 9 s). Max span: 10 tiles (base 8).', '{"time:bridge_stone":0.7,"span:bridge_stone":10}');
insert into class_perk values ('mason_salvage', 'mason', 5, 16, 'Salvage', 'Remove wall returns 50% of the stone in a wall of stone, anything but log, plank or timbercraft, rounded down: stone-brick wall 12 of 24 stone bricks (base: none).', '{"salvage:build_stone":0.5}');
insert into class_perk values ('mason_hod_carrier', 'mason', 5, 35, 'Hod Carrier', 'Build wall and Build floor on stone, anything but log, plank or timbercraft: take from crates, carts and craft-reachable containers within 5 tiles (base 3), with Use stores within reach on or off.', '{"reach:build_stone":5}');
insert into class_perk values ('mason_rubble_fill', 'mason', 5, 48, 'Rubble Fill', 'New action: Raise the rock with rubble. Raises a bare rock corner 0.1 m for 5 rock shards instead of a concrete; same rules and check (difficulty 10) as concrete.', '{"rubble":5}');
insert into class_perk values ('mason_tall_walls', 'mason', 6, 12, 'Tall Walls', 'Max storeys of stone in buildings you planned: +2, max 12 (base marble, stone brick, ornate silver, ornate gold and stained glass 10, slate 8, sandstone and clay bricks 7, cobblestone 6, clay adobe 5; max 10). Timber unchanged; a building is capped by its shortest material. Each storey above 10 needs masonry 100 on the storey below.', '{"storeys:build_stone":2}');
insert into class_perk values ('mason_nothing_wasted', 'mason', 6, 24, 'Careful Builder', 'Failed smelter or kiln: materials kept (base: lost).', '{"spare:make_smelter":1,"spare:make_kiln":1}');
insert into class_perk values ('mason_repoint', 'mason', 6, 47, 'Repoint', 'New action: Repoint, on a finished wall of stone, anything but log, plank or timbercraft. Relays it in another stone in one action: 30 s base. Cost: the new stone''s full bill. Returns 50% of the old stone, rounded down.', '{"repoint":1}');
insert into class_perk values ('carpenter_quick_saw', 'carpenter', 1, 1, 'Quick Saw', 'Saw into planks, Saw into timbers and Carve shafts time −30% (base 5 s).', '{"time:make_planks":0.7,"time:make_timbers":0.7,"time:make_shafts":0.7}');
insert into class_perk values ('carpenter_string_maker', 'carpenter', 1, 37, 'String Maker', 'Twist a bowstring: 1 yarn (base 2), never fails (base: check at difficulty 14).', '{"need:make_bow_string":0.5,"fail:make_bow_string":0}');
insert into class_perk values ('carpenter_saw_care', 'carpenter', 1, 45, 'Saw Care', 'Tool damage per use ×0.5: saws, carving knives, mallets and files, any quality and material.', '{"wear:saw":0.5,"wear:carving_knife":0.5,"wear:mallet":0.5,"wear:file":0.5}');
insert into class_perk values ('carpenter_heavy_timber', 'carpenter', 2, 3, 'Heavy Timber', 'Saw into timbers: 3 timbers per log (base 2).', '{"count:timber":3}');
insert into class_perk values ('carpenter_thatcher', 'carpenter', 2, 6, 'Thatcher', 'Bundle into thatch: 2 thatch per 2 mixed grass (base 1).', '{"count:thatch":2}');
insert into class_perk values ('carpenter_shipwright', 'carpenter', 2, 14, 'Shipwright', 'Build time −30%: rowing boat, sailing boat and caravel (base 34 s, 70 s and 180 s).', '{"time:make_rowing_boat":0.7,"time:make_sailing_boat":0.7,"time:make_caravel":0.7}');
insert into class_perk values ('carpenter_keel_layer', 'carpenter', 3, 15, 'Keel Layer', 'Boat speed +10% on boats you build, at fair effort, in tiles/s: rowing boat 2.1, sailing boat 3.7 and caravel 4.4 (base 1.9, 3.4 and 4). Stays with the boat.', '{"speed:rowing_boat":1.1,"speed:sailing_boat":1.1,"speed:caravel":1.1}');
insert into class_perk values ('carpenter_timber_salvage', 'carpenter', 3, 26, 'Timber Salvage', 'Remove wall returns 50% of the logs or planks in a wall of log, plank or timbercraft, rounded down: plank wall 12 of 24 planks (base: none).', '{"salvage:build_wood":0.5}');
insert into class_perk values ('carpenter_bowyers_draw', 'carpenter', 3, 31, 'Bowyer''s Draw', 'Bow damage +10% on bows you make, base damage: short bow 8.8, medium bow 12.1, long bow 16.5 and composite bow 23.1 (base 8, 11, 15 and 21). Stays with the bow.', '{"damage:short_bow":1.1,"damage:medium_bow":1.1,"damage:long_bow":1.1,"damage:composite_bow":1.1}');
insert into class_perk values ('carpenter_deep_hold', 'carpenter', 4, 16, 'Deep Hold', 'Boat capacity +25% on boats you build, before wood and rarity: rowing boat 375, sailing boat 1875 and caravel 6250 (base 300, 1500 and 5000). Stays with the boat.', '{"hold:rowing_boat":1.25,"hold:sailing_boat":1.25,"hold:caravel":1.25}');
insert into class_perk values ('carpenter_sure_hull', 'carpenter', 4, 19, 'Sure Hull', 'Boat, cart and wagon building failure chance ×0.5 (base: check at difficulty 18–60).', '{"fail:make_cart":0.5,"fail:make_large_cart":0.5,"fail:make_wagon":0.5,"fail:make_rowing_boat":0.5,"fail:make_sailing_boat":0.5,"fail:make_caravel":0.5}');
insert into class_perk values ('carpenter_true_bow', 'carpenter', 4, 32, 'True Bow', 'Bow range +10% on bows you make, in tiles: short bow 6.6, medium bow 9.9, long bow 14.3 and composite bow 18.7 (base 6, 9, 13 and 17). Stays with the bow.', '{"range:short_bow":1.1,"range:medium_bow":1.1,"range:long_bow":1.1,"range:composite_bow":1.1}');
insert into class_perk values ('carpenter_clean_sawing', 'carpenter', 5, 2, 'Clean Sawing', 'Saw into planks: 4 planks per log (base 3).', '{"count:plank":4}');
insert into class_perk values ('carpenter_smooth_axle', 'carpenter', 5, 18, 'Smooth Axle', 'Vehicle speed +10%: large carts and wagons you build. Max 4.4 tiles/s (base max 4). Stays with the vehicle.', '{"speed:large_cart":1.1,"speed:wagon":1.1}');
insert into class_perk values ('carpenter_fence_builder', 'carpenter', 5, 25, 'Fence Builder', 'Fences, fence gates, iron-bound gates, half walls and rune gates: time ×0.5 (base 5 s), material ×0.5 rounded up. Plank fence: 4 planks and 1 timber (base 8 planks and 2 timbers). Hinges and brackets unchanged.', '{"time:fence":0.5,"bill:fence":0.5}');
insert into class_perk values ('carpenter_master_joiner', 'carpenter', 6, 10, 'Master Joiner', 'Rare chance on carpentry and fine carpentry furniture (51 pieces, boats, carts and wagons included): 1 in 50 (base 1 in 100). Supreme and fantastic at usual odds.', '{"rare:make_stool":0.02,"rare:make_chair":0.02,"rare:make_bench":0.02,"rare:make_table":0.02,"rare:make_long_table":0.02,"rare:make_desk":0.02,"rare:make_bed":0.02,"rare:make_cot":0.02,"rare:make_den_small":0.02,"rare:make_den_medium":0.02,"rare:make_den_large":0.02,"rare:make_chest":0.02,"rare:make_coffer":0.02,"rare:make_cupboard":0.02,"rare:make_wardrobe":0.02,"rare:make_shelves":0.02,"rare:make_bookshelf":0.02,"rare:make_larder":0.02,"rare:make_barrel":0.02,"rare:make_stall":0.02,"rare:make_mailbox":0.02,"rare:make_creature_crate":0.02,"rare:make_lectern":0.02,"rare:make_coat_rack":0.02,"rare:make_planter":0.02,"rare:make_trellis":0.02,"rare:make_firewood_rack":0.02,"rare:make_crate_shelf":0.02,"rare:make_bell":0.02,"rare:make_hive":0.02,"rare:make_spindle":0.02,"rare:make_loom":0.02,"rare:make_paper_press":0.02,"rare:make_butter_churn":0.02,"rare:make_lamp_post":0.02,"rare:make_rose_arch":0.02,"rare:make_bulk_bin":0.02,"rare:make_craft_bin":0.02,"rare:make_seed_bin":0.02,"rare:make_sprout_bin":0.02,"rare:make_trash_crate":0.02,"rare:make_cart":0.02,"rare:make_large_cart":0.02,"rare:make_wagon":0.02,"rare:make_rowing_boat":0.02,"rare:make_sailing_boat":0.02,"rare:make_caravel":0.02,"rare:make_small_barrel":0.02,"rare:make_large_barrel":0.02,"rare:make_sign":0.02,"rare:make_great_sign":0.02}');
insert into class_perk values ('carpenter_deep_drawers', 'carpenter', 6, 12, 'Deep Drawers', 'Capacity +20%, before wood and rarity: chests, coffers, cupboards, wardrobes, shelves, bookshelves, larders, small barrels, barrels, large barrels, raw material bins, craft material bins, seed bins and sprout bins you make. Chest 72 (base 60), barrel 96 litres (base 80). Stays with the piece.', '{"hold:chest":1.2,"hold:coffer":1.2,"hold:cupboard":1.2,"hold:wardrobe":1.2,"hold:shelves":1.2,"hold:bookshelf":1.2,"hold:larder":1.2,"hold:small_barrel":1.2,"hold:barrel":1.2,"hold:large_barrel":1.2,"hold:bulk_bin":1.2,"hold:craft_bin":1.2,"hold:seed_bin":1.2,"hold:sprout_bin":1.2}');
insert into class_perk values ('carpenter_bridge_wright', 'carpenter', 6, 27, 'Bridge Wright', 'Wooden bridge and rope bridge work time −30% (base 9 s). Max span +2 tiles: 12 and 16 (base 10 and 14).', '{"time:bridge_wood":0.7,"time:bridge_rope":0.7,"span:bridge_wood":12,"span:bridge_rope":16}');
insert into class_perk values ('smith_glassblower', 'smith', 1, 8, 'Glassblower', 'Melt into glass: 3 glass lump per 3 sand (base 2).', '{"count:glass_lump":3}');
insert into class_perk values ('smith_mail_maker', 'smith', 1, 26, 'Mail Maker', 'Damage stopped +10% on chain you beat out, max 92%: chain coif, chain hauberk, chain sleeves, chain leggings and chain boots. 46% chain stops 50.6%. Stays with the piece.', '{"soak:chain_coif":1.1,"soak:chain_hauberk":1.1,"soak:chain_sleeves":1.1,"soak:chain_leggings":1.1,"soak:chain_boots":1.1}');
insert into class_perk values ('smith_plate_maker', 'smith', 1, 27, 'Plate Maker', 'Damage stopped +10% on plate you beat out, max 92%: helm, breastplate, plate arms, plate legs and plate boots. 62% plate stops 68.2%. Stays with the piece.', '{"soak:helm":1.1,"soak:plate_breastplate":1.1,"soak:plate_arms":1.1,"soak:plate_legs":1.1,"soak:plate_boots":1.1}');
insert into class_perk values ('smith_toolsmith', 'smith', 2, 30, 'Toolsmith', 'QL +10% on tool heads and blades you beat out: rake heads, shovel heads, hatchet heads, sickle blades, pickaxe heads, hammer heads, knife blades, saw blades and trowel blades. QL 50 becomes 55.', '{"ql:rake_head":1.1,"ql:shovel_head":1.1,"ql:hatchet_head":1.1,"ql:sickle_blade":1.1,"ql:pickaxe_head":1.1,"ql:hammer_head":1.1,"ql:knife_blade":1.1,"ql:saw_blade":1.1,"ql:trowel_blade":1.1}');
insert into class_perk values ('smith_metal_polisher', 'smith', 2, 32, 'Metal Polisher', 'Improve gain per pass +50% on metal. At skill 50, QL 40: 3.3 per pass (base 2.2).', '{"improve:metal":1.5}');
insert into class_perk values ('smith_ingots', 'smith', 2, 49, 'Ingots', 'New smelter recipe: ingot from 5 lumps of a metal, at the lumps'' QL. Weight ×0.5 of its lumps. Counts as 5 lumps at the smelter, anvil, recipes and Improve; unused lumps are returned.', '{"ingot":1}');
insert into class_perk values ('smith_hard_sand', 'smith', 3, 12, 'Hard Sand', 'Mould uses ×2 on moulds you make, all but the anvil mould (one use). QL 50 mould: 14 copper fillings (base 7). Stays with the mould.', '{"last:pan_mould":2,"last:rake_head_mould":2,"last:shovel_head_mould":2,"last:hatchet_head_mould":2,"last:sickle_blade_mould":2,"last:pickaxe_head_mould":2,"last:hammer_head_mould":2,"last:knife_blade_mould":2,"last:sword_blade_mould":2,"last:helm_mould":2,"last:nail_mould":2,"last:ribbon_mould":2,"last:axle_mould":2,"last:arrow_head_mould":2,"last:short_sword_blade_mould":2,"last:long_sword_blade_mould":2,"last:axe_head_mould":2,"last:maul_head_mould":2,"last:spear_head_mould":2,"last:shield_boss_mould":2,"last:file_mould":2,"last:chisel_mould":2,"last:saw_blade_mould":2,"last:trowel_blade_mould":2,"last:coin_die_mould":2,"last:horseshoe_mould":2,"last:hinge_mould":2,"last:bracket_mould":2,"last:ring_mould":2,"last:pendant_mould":2,"last:bell_mould":2,"last:statue_mould":2,"last:chain_coif_mould":2,"last:chain_hauberk_mould":2,"last:chain_sleeves_mould":2,"last:chain_leggings_mould":2,"last:chain_boots_mould":2,"last:plate_breastplate_mould":2,"last:plate_arms_mould":2,"last:plate_legs_mould":2,"last:plate_boots_mould":2}');
insert into class_perk values ('smith_second_heat', 'smith', 3, 20, 'Second Heat', 'Failed Smith: casting kept for another try (base: metal lost).', '{"spare:smith":1}');
insert into class_perk values ('smith_nail_maker', 'smith', 3, 22, 'Nail Maker', 'Nails per nail-mould filling: 8 (base 5). 8 nails per iron lump, per 10 gold.', '{"count:nail":8}');
insert into class_perk values ('smith_keen_edge', 'smith', 4, 24, 'Keen Edge', 'Weapon damage +10% on weapons fitted from heads and blades you beat out, by anyone: hatchets, butchering knives, swords, short swords, long swords, battle axes, mauls, spears, hunting knives, carving knives, javelins and throwing axes. Sword 11 base damage (base 10). Passes from part to weapon and stays with it.', '{"damage:hatchet_head":1.1,"damage:knife_blade":1.1,"damage:sword_blade":1.1,"damage:arrow_head":1.1,"damage:short_sword_blade":1.1,"damage:long_sword_blade":1.1,"damage:axe_head":1.1,"damage:maul_head":1.1,"damage:spear_head":1.1}');
insert into class_perk values ('smith_balanced', 'smith', 4, 25, 'Balanced', 'Hit chance +5% on weapons fitted from heads and blades you beat out, by anyone; max 96%. A 70% swing hits 73.5%. Passes from part to weapon and stays with it.', '{"aim:hatchet_head":1.05,"aim:knife_blade":1.05,"aim:sword_blade":1.05,"aim:arrow_head":1.05,"aim:short_sword_blade":1.05,"aim:long_sword_blade":1.05,"aim:axe_head":1.05,"aim:maul_head":1.05,"aim:spear_head":1.05}');
insert into class_perk values ('smith_forge_reach', 'smith', 4, 36, 'Forge Reach', 'Smelter and anvil work takes from your stores within 6 tiles (base 3): smelt, melt down, cast an anvil, pour a mould, pour ingots, fuel, smith and strike coins and every smelter recipe.', '{"reach:forge":6}');
insert into class_perk values ('smith_sure_alloy', 'smith', 5, 7, 'Sure Alloy', 'Mix bronze, Make steel, Mix brass, Mix pewter and Mix electrum failure chance ×0.5 (base: check at difficulty 10–20).', '{"fail:make_bronze":0.5,"fail:make_steel":0.5,"fail:make_brass":0.5,"fail:make_pewter":0.5,"fail:make_electrum":0.5}');
insert into class_perk values ('smith_reclaimer', 'smith', 5, 9, 'Reclaimer', 'Melt down returns 75% of an item''s lumps at 85% of its QL minus damage (base 50% at 70%). Chain hauberk: 4 lumps (base 3).', '{"melt:share":0.75,"melt:keep":0.85}');
insert into class_perk values ('smith_clean_pour', 'smith', 5, 13, 'Clean Pour', 'Mould damage counted against the pour: none (base ×0.5). QL 50 mould at 40 damage pours as 50 (base 30); the casting also counts lump QL and smelting.', '{"pour:wear":0}');
insert into class_perk values ('smith_sure_hammer', 'smith', 6, 16, 'Sure Hammer', 'Smith and Strike coins failure chance ×0.5 (base: check at difficulty 6–32 for a piece, 12 for coins, more for hard metals).', '{"fail:smith":0.5,"fail:strike_coins":0.5}');
insert into class_perk values ('smith_masters_mark', 'smith', 6, 19, 'Master’s Mark', 'Rare chance at the anvil: 1 in 50 (base 1 in 100). Supreme and fantastic at usual odds.', '{"rare:smith":0.02}');
insert into class_perk values ('smith_temper_bath', 'smith', 6, 45, 'Temper Bath', 'New action: Quench, at water or beside a barrel or well of it, by you or any Smith with Temper Bath. +5 QL, once, on a weapon or tool you finish: rakes, shovels, hatchets, sickles, hammers, pickaxes, butchering knives, swords, short swords, long swords, battle axes, mauls, spears, hunting knives, carving knives, saws, trowels, javelins, throwing axes, frying pans, files, stone chisels and coin dies (fitted from an anvil-beaten head or blade, or anvil-beaten whole). Stays with the item until quenched.', '{"temper:rake":5,"temper:shovel":5,"temper:hatchet":5,"temper:sickle":5,"temper:hammer":5,"temper:pickaxe":5,"temper:butchering_knife":5,"temper:sword":5,"temper:short_sword":5,"temper:long_sword":5,"temper:battle_axe":5,"temper:maul":5,"temper:spear":5,"temper:hunting_knife":5,"temper:carving_knife":5,"temper:saw":5,"temper:trowel":5,"temper:javelin":5,"temper:throwing_axe":5,"temper:frying_pan":5,"temper:file":5,"temper:chisel":5,"temper:coin_die":5}');
insert into class_perk values ('forester_woodsmans_stride', 'forester', 1, 34, 'Woodsman''s Stride', 'Full walk speed on foot through bush, reed, stump and marsh (base bush 50%, reed 80%, stump 70% and marsh 60%).', '{"walk:bush":2,"walk:reed":1.25,"walk:stump":1.4285714285714286,"walk:marsh":1.6666666666666667}');
insert into class_perk values ('forester_tap_resin', 'forester', 1, 43, 'Tap Resin', 'New action: Tap resin (carving knife, 6 s). 1 tar from a living pine, once a day per tree; day starts at the daily reset (13:00 UTC).', '{"tap_resin":1}');
insert into class_perk values ('forester_clear_brush', 'forester', 1, 44, 'Clear Brush', 'New action: Clear brush (sickle, 16 s). Clears every bush and reed in a 3×3 area at once. Bush leaves grass, reed leaves dirt. No output.', '{"clear_brush":1}');
insert into class_perk values ('forester_nest_finder', 'forester', 2, 21, 'Nest Finder', 'Tree felled for timber: 1 in 10 give 3 feathers at the logs'' QL.', '{"nest:chance":0.1,"nest:feathers":3}');
insert into class_perk values ('forester_honey_hunter', 'forester', 2, 22, 'Honey Hunter', 'Tree felled for timber: 1 in 20 give 2 honey at the logs'' QL.', '{"honey:chance":0.05,"honey:count":2}');
insert into class_perk values ('forester_coppice', 'forester', 2, 40, 'Coppice', 'New action: Coppice (hatchet, 8 s, check at difficulty 10). Cuts mature, old or very old trees back to young for 2 logs; the tree stays standing.', '{"coppice":2}');
insert into class_perk values ('forester_clean_stroke', 'forester', 3, 1, 'Clean Stroke', 'Cut down time per stroke −25% (base 8 s), trees and bushes.', '{"time:cut_down":0.75}');
insert into class_perk values ('forester_heavy_swing', 'forester', 3, 2, 'Heavy Swing', 'Strokes to fell a tree −1, min one: young 1 (base 2), mature 2 (base 3), old 2 (base 3), very old 3 (base 4) and shrivelled 1 (base 2).', '{"fewer:cut_down":1}');
insert into class_perk values ('forester_sure_hatchet', 'forester', 3, 3, 'Sure Hatchet', 'Cut down failure chance ×0.5 (base: check at difficulty 10), trees and bushes.', '{"fail:cut_down":0.5}');
insert into class_perk values ('forester_clean_drop', 'forester', 4, 7, 'Clean Drop', 'Felled tree leaves grass (base: a stump, for a day or until dug out).', '{"stump:clear":1}');
insert into class_perk values ('forester_fruitful', 'forester', 4, 16, 'Fruitful', 'Pick fruit: one extra fruit on every pick.', '{"more:pick_fruit":1}');
insert into class_perk values ('forester_kindling', 'forester', 4, 24, 'Kindling', 'Cut down a bush: 2 shafts (base: none).', '{"bush:shaft":2}');
insert into class_perk values ('forester_sprout_picker', 'forester', 5, 10, 'Sprout Picker', 'Pick sprout never fails (base: check at difficulty 15). Sprouts per action: 2 (base one).', '{"fail:pick_sprout":0,"count:sprout":2}');
insert into class_perk values ('forester_nursery', 'forester', 5, 11, 'Nursery', 'Planted sprout age: mature (base young). Logs when felled: 4 (base 2). Fruit trees bear at once.', '{"grown:plant":1}');
insert into class_perk values ('forester_hedge_harvest', 'forester', 5, 20, 'Hedge Harvest', 'Bush harvest: one extra rose petals or lavender on every action.', '{"more:harvest_bush":1}');
insert into class_perk values ('forester_choice_logs', 'forester', 6, 5, 'Choice Logs', 'Felled log QL +10%.', '{"ql:cut_down":1.1}');
insert into class_perk values ('forester_rare_heartwood', 'forester', 6, 6, 'Rare Heartwood', 'Rare log chance per tree felled: 1 in 100 (base: none). Rare may become supreme or fantastic at crafting odds.', '{"rare:cut_down":0.01}');
insert into class_perk values ('forester_master_grafter', 'forester', 6, 14, 'Master Grafter', 'Graft never fails (base: check at difficulty 40; sprout used either way). Time −30% (base 8 s).', '{"fail:graft":0,"time:graft":0.7}');
insert into class_perk values ('farmer_fodder', 'farmer', 1, 14, 'Fodder', 'Harvest: +2 mixed grass at the harvest''s QL, into your pack.', '{"fodder:harvest_crop":2}');
insert into class_perk values ('farmer_milkmaid', 'farmer', 1, 25, 'Milkmaid', 'Milking time −40% (base 6 s). Cudda: second bucket of milk on 1 in 2 actions, if you carry another empty bucket. Gorral: 2 litres per milking either way.', '{"time:milk_creature":0.6,"more:milk_creature":0.5}');
insert into class_perk values ('farmer_sack_porter', 'farmer', 1, 28, 'Sack Porter', 'Weight −50%: produce and seed of every crop, flour, cornmeal. Potato 0.1 kg per unit (base 0.2 kg), wheat seeds 0.01 kg per unit (base 0.02 kg) and flour 0.05 kg per unit (base 0.1 kg).', '{"weight:onion":0.5,"weight:onion_seed":0.5,"weight:carrot":0.5,"weight:carrot_seed":0.5,"weight:cabbage":0.5,"weight:cabbage_seed":0.5,"weight:potato":0.5,"weight:potato_seed":0.5,"weight:wheat":0.5,"weight:wheat_seed":0.5,"weight:corn":0.5,"weight:corn_seed":0.5,"weight:sage":0.5,"weight:sage_seed":0.5,"weight:basil":0.5,"weight:basil_seed":0.5,"weight:thyme":0.5,"weight:thyme_seed":0.5,"weight:mint":0.5,"weight:mint_seed":0.5,"weight:rosemary":0.5,"weight:rosemary_seed":0.5,"weight:cotton":0.5,"weight:cotton_seed":0.5,"weight:wemp":0.5,"weight:wemp_seed":0.5,"weight:flour":0.5,"weight:cornmeal":0.5}');
insert into class_perk values ('farmer_seed_saver', 'farmer', 2, 4, 'Seed Saver', 'Sow and Sow a patch use no seed: 1 in 4 fields.', '{"keep:plant_seed":0.25}');
insert into class_perk values ('farmer_fast_growth', 'farmer', 2, 5, 'Fast Growth', 'Crop growth stage time −20% on crops you sow: mint 100 s (base 125 s) to corn 300 s (base 375 s).', '{"grow:plant_seed":0.8}');
insert into class_perk values ('farmer_bumper_crop', 'farmer', 2, 8, 'Bumper Crop', 'Harvest of a crop tended at all 3 growth stages: 5 produce (base 4).', '{"bumper:harvest_crop":1}');
insert into class_perk values ('farmer_more_meal', 'farmer', 3, 22, 'More Meal', 'Grind into flour: 2 flour per action (base 1). Grind into cornmeal: 2 cornmeal (base 1).', '{"count:flour":2,"count:cornmeal":2}');
insert into class_perk values ('farmer_full_press', 'farmer', 3, 23, 'Full Press', 'Quern juice, cider and olive oil: fruit needed −20%, 8 (base 10) and 16 (base 20); output per fruit +25%. Juice and cider: one bucket per pressing.', '{"need:press_olives":0.8,"need:press_apple_juice":0.8,"need:press_cherry_juice":0.8,"need:press_olive_juice":0.8,"need:press_pear_juice":0.8,"need:press_plum_juice":0.8,"need:press_peach_juice":0.8,"need:press_fig_juice":0.8,"need:press_lemon_juice":0.8,"need:press_pomegranate_juice":0.8,"need:press_apricot_juice":0.8,"need:press_quince_juice":0.8,"need:press_apple_cider":0.8,"need:press_pear_cider":0.8}');
insert into class_perk values ('farmer_barn_reach', 'farmer', 3, 30, 'Barn Reach', 'Harvest and Harvest a patch output goes into the nearest unlocked cart or wagon not pulled or driven by another player, or container you built or on your settlement, within 5 tiles (base: your pack).', '{"into:harvest_crop":5,"into:harvest_patch":5}');
insert into class_perk values ('farmer_crop_rotation', 'farmer', 4, 6, 'Crop Rotation', 'Crop growth stage time −25% on a field last sown with a different crop: mint 93.8 s (base 125 s) to corn 281.3 s (base 375 s). A field never sown, or broken up since, has no last crop.', '{"rotate:plant_seed":0.75}');
insert into class_perk values ('farmer_worn_in_rake', 'farmer', 4, 34, 'Worn-in Rake', 'Rake QL counts +20 when tilling, max 100: Till time −5% (base 5 s; each tool QL point −0.3% of an action''s time).', '{"tool:till":20}');
insert into class_perk values ('farmer_sow_a_patch', 'farmer', 4, 39, 'Sow a Patch', 'New action: Sow a patch (9 s, the time of 3 sowings). Sows the chosen seed on every empty field in a 3×3 area, one seed per field.', '{"sow_patch":1}');
insert into class_perk values ('farmer_rare_harvest', 'farmer', 5, 11, 'Rare Harvest', 'Rare harvest chance: 1 in 100 crops (base: none); seed is never rare. Rare may become supreme or fantastic at crafting odds.', '{"rare:harvest_crop":0.01}');
insert into class_perk values ('farmer_tend_a_patch', 'farmer', 5, 40, 'Tend a Patch', 'New action: Tend patch (12 s, the time of 3 tendings). Tends every unripe crop not yet tended at its growth stage in a 3×3 area.', '{"tend_patch":1}');
insert into class_perk values ('farmer_harvest_a_patch', 'farmer', 5, 41, 'Harvest a Patch', 'New action: Harvest patch (15 s, the time of 3 harvests). Harvests every ripe crop in a 3×3 area, each by its own tending.', '{"harvest_patch":1}');
insert into class_perk values ('farmer_herb_plot', 'farmer', 6, 15, 'Herb Plot', 'Harvest +2: sage, basil, thyme, mint and rosemary.', '{"plus:sage":2,"plus:basil":2,"plus:thyme":2,"plus:mint":2,"plus:rosemary":2}');
insert into class_perk values ('farmer_grain_master', 'farmer', 6, 16, 'Grain Master', 'Harvest +2: wheat and corn.', '{"plus:wheat":2,"plus:corn":2}');
insert into class_perk values ('farmer_fibre_farmer', 'farmer', 6, 17, 'Fibre Farmer', 'Harvest +2: cotton and wemp.', '{"plus:cotton":2,"plus:wemp":2}');
insert into class_perk values ('cook_flavoursome', 'cook', 1, 11, 'Flavoursome', 'Meal boost duration +50%, dishes you cook, for whoever eats them.', '{"knack:cheese":1.5,"knack:butter":1.5,"knack:cooked_meat":1.5,"knack:baked_potato":1.5,"knack:roast_onion":1.5,"knack:roast_nuts":1.5,"knack:roast_lotus_seeds":1.5,"knack:berry_compote":1.5,"knack:pottage":1.5,"knack:preserves":1.5,"knack:bread":1.5,"knack:porridge":1.5,"knack:pastry":1.5,"knack:apple_pie":1.5,"knack:broth":1.5,"knack:stew":1.5,"knack:cooked_fish":1.5}');
insert into class_perk values ('cook_full_carcass', 'cook', 1, 18, 'Full Carcass', 'Butchering yield +15%, max the whole carcass.', '{"share:butcher":1.15}');
insert into class_perk values ('cook_strong_brew', 'cook', 1, 28, 'Strong Brew', 'Drink boost duration +50%: ale, cider, mead, wine and grape wine you brew, for whoever drinks it, from the barrel or a bucket drawn off it.', '{"brewed:ale":1.5,"brewed:cider":1.5,"brewed:mead":1.5,"brewed:wine":1.5,"brewed:grape_wine":1.5}');
insert into class_perk values ('cook_pantry_reach', 'cook', 2, 31, 'Pantry Reach', 'Cooking takes ingredients from containers within 6 tiles (base 3).', '{"reach:cook":6}');
insert into class_perk values ('cook_bait_maker', 'cook', 2, 49, 'Bait Maker', 'Butchering: +2 offal (fishing bait; draws trout and pike).', '{"bait:butcher":2}');
