insert into class_perk values ('fisher_cool_pack', 'fisher', 3, 25, 'Cool Pack', 'Rot rate on the ground −50%: minnow, perch, trout, pike and sturgeon you drop, until picked up. Nothing rots in a pack.', '{"cool:minnow":0.5,"cool:perch":0.5,"cool:trout":0.5,"cool:pike":0.5,"cool:sturgeon":0.5}');
insert into class_perk values ('fisher_rod_care', 'fisher', 3, 33, 'Rod Care', 'Fishing rod damage per cast ×0.5, any quality and wood.', '{"wear:fishing_rod":0.5}');
insert into class_perk values ('fisher_steady_hand', 'fisher', 4, 3, 'Steady Hand', 'Hook chance on a bite +15 percentage points, after all other factors (max 95%).', '{"hook:fish":0.15}');
insert into class_perk values ('fisher_full_net', 'fisher', 4, 14, 'Full Net', 'Net haul +2 fish: 3 to 7 by net QL (base 1 to 5), before the maker''s bonus.', '{"haul:drag_net":2}');
insert into class_perk values ('fisher_deep_creel', 'fisher', 4, 19, 'Deep Creel', 'Creel capacity, creels you make: 16 fish (base 8).', '{"hold:creel":2}');
insert into class_perk values ('fisher_strong_bait', 'fisher', 5, 5, 'Strong Bait', 'Bait pull ×2, on the hook and in creels you set: 16× plain weight for its first favoured fish, 8× for the second (base 8× and 4×).', '{"bait:pull":2}');
insert into class_perk values ('fisher_any_bait', 'fisher', 5, 6, 'Any Bait', 'With no fish bait in your pack, any food works as bait on the hook or in a creel: draws every fish at plain weight, hook chance +12 percentage points as any bait (base: only worms, corn, minnow, meat, perch or offal).', '{"bait:food":1}');
insert into class_perk values ('fisher_big_fish', 'fisher', 5, 9, 'Big Fish', 'Bite weight ×2: trout, pike and sturgeon, on your rod, your net and creels you set. With every fish present and no bait: 50.9% of bites (base 34.1%).', '{"bite:trout":2,"bite:pike":2,"bite:sturgeon":2}');
insert into class_perk values ('fisher_rare_catch', 'fisher', 6, 12, 'Rare Catch', 'Rare chance on fish landed by rod or net: 1 in 100 (base: none). Supreme and fantastic at usual odds.', '{"rare:fish":0.01,"rare:drag_net":0.01}');
insert into class_perk values ('fisher_smoke_fish', 'fisher', 6, 27, 'Smoke Fish', 'New recipe: smoke a fish over a lit campfire, on fishing, at the fish''s QL. Rot rate −80% anywhere: keeps ×5 as long.', '{"smoke_fish":1,"rot:minnow":0.2,"rot:perch":0.2,"rot:trout":0.2,"rot:pike":0.2,"rot:sturgeon":0.2}');
insert into class_perk values ('fisher_fish_pond', 'fisher', 6, 47, 'Fish Pond', 'New build: fish pond (20 clay, 12 rock shards and 8 reeds, shovel), on your settlement. Restock time per fish: 1 h, max 10 fish, every fish at plain weight.', '{"fish_pond":1}');
insert into class_perk values ('mender_quick_hands', 'mender', 1, 4, 'Quick Hands', 'Repair time −40%: 2.7 s (base 4.5 s, the minimum for any action without a perk).', '{"time:repair_item":0.6}');
insert into class_perk values ('mender_tool_care', 'mender', 1, 9, 'Tool Care', 'Tool damage per use −25%: every tool, any action and material.', '{"wear:awl":0.75,"wear:brush":0.75,"wear:butchering_knife":0.75,"wear:carving_knife":0.75,"wear:chisel":0.75,"wear:clay_bowl":0.75,"wear:clay_jar":0.75,"wear:clay_pot":0.75,"wear:file":0.75,"wear:fishing_net":0.75,"wear:fishing_rod":0.75,"wear:frying_pan":0.75,"wear:hammer":0.75,"wear:hatchet":0.75,"wear:mallet":0.75,"wear:needle":0.75,"wear:pickaxe":0.75,"wear:quern":0.75,"wear:rake":0.75,"wear:rope_tool":0.75,"wear:saw":0.75,"wear:shovel":0.75,"wear:sickle":0.75,"wear:trowel":0.75}');
insert into class_perk values ('mender_quick_restore', 'mender', 1, 17, 'Quick Restore', 'Relic and bauble restoring time −40% (base 20 s).', '{"time:restore_relic":0.6}');
insert into class_perk values ('mender_clean_repair', 'mender', 2, 3, 'Clean Repair', 'Repair costs no QL: 1 in 4 actions.', '{"keep:repair_item":0.25}');
insert into class_perk values ('mender_armour_care', 'mender', 2, 10, 'Armour Care', 'Damage to your gear −25%: armour per blow taken, shield −25% per blow blocked, weapon −25% per blow or arrow landed.', '{"worn:armour":0.75,"worn:shield":0.75,"worn:weapon":0.75}');
insert into class_perk values ('mender_gentle_hands', 'mender', 2, 19, 'Gentle Hands', 'Damage from a failed restoring: none (base 5 to 14 to each piece or the bauble).', '{"harm:restore_relic":0}');
insert into class_perk values ('mender_big_mend', 'mender', 3, 1, 'Big Mend', 'Damage removed per Repair action +50%, same QL cost per point: 12.3 at repair 70 (base 8.2).', '{"mend:repair_item":1.5}');
insert into class_perk values ('mender_post_keeper', 'mender', 3, 14, 'Post Keeper', 'Duration +50%: work posts, snares, creels and deadfalls you set. Work post 1 h 53 min to 4 h 30 min by QL (base 1 h 15 min to 3 h).', '{"life:work_post":1.5,"life:snare":1.5,"life:creel":1.5,"life:deadfall":1.5}');
insert into class_perk values ('mender_sure_restore', 'mender', 3, 18, 'Sure Restore', 'Relic and bauble restoring failure chance ×0.5.', '{"fail:restore_relic":0.5}');
insert into class_perk values ('mender_light_touch', 'mender', 4, 2, 'Light Touch', 'Repair QL cost per damage point ×0.5: 0.0046 QL at repair 80 (base 0.0092).', '{"cost:repair_item":0.5}');
insert into class_perk values ('mender_fine_restore', 'mender', 4, 20, 'Fine Restore', 'Restored relic and bauble QL +10%, max 100.', '{"ql:restore_relic":1.1}');
insert into class_perk values ('mender_age_undone', 'mender', 4, 21, 'Age Undone', 'QL lost to damage on the pieces or bauble when restoring: none (base 0.5% per damage point).', '{"age:restore_relic":0}');
insert into class_perk values ('mender_lucky_polish', 'mender', 5, 24, 'Lucky Polish', 'Rare chance on baubles you restore: 1 in 50 (base 1 in 100). Supreme and fantastic at usual odds.', '{"rare:restore_relic":0.02}');
insert into class_perk values ('mender_second_look', 'mender', 5, 25, 'Second Look', 'Minor and major baubles you restore: strength drawn 2 times, best kept (each draw 1–5% before rarity). Ancient baubles unchanged.', '{"rolls:bauble":2}');
insert into class_perk values ('mender_repair_kit', 'mender', 5, 42, 'Repair Kit', 'New recipe, on repair: 2 cloth, 2 nails and a plank with a hammer make a repair kit. Per use: −50 damage on any item, anywhere, no QL loss. Usable by anyone.', '{"repair_kit":1}');
insert into class_perk values ('mender_tier_up', 'mender', 6, 26, 'Grade Up', 'Baubles you restore come out one grade higher: 1 in 10 (minor → major, major → ancient).', '{"tier:restore_relic":0.1}');
insert into class_perk values ('mender_handyman', 'mender', 6, 27, 'Handyman', 'Improve anything to QL 30 regardless of skill (base 10); above that, skill is the cap.', '{"floor:improve":30}');
insert into class_perk values ('mender_sealant', 'mender', 6, 50, 'Sealant', 'New recipe, on repair: a tar and a beeswax make sealant. Applied item never decays, anywhere: one per item, one per item in a pile. Usable by anyone.', '{"sealant":1}');
insert into class_perk values ('artisan_sure_setting', 'artisan', 1, 2, 'Sure Setting', 'Stone setting failure chance ×0.5: ring, pendant, focus and circlet.', '{"fail:set_ring":0.5,"fail:set_pendant":0.5,"fail:set_focus":0.5,"fail:set_in_circlet":0.5}');
insert into class_perk values ('artisan_keep_the_stone', 'artisan', 1, 3, 'Keep the Stone', 'Failed focus setting: stone returned whole, only the silver lost (base: stone splits).', '{"stone:set_focus":1}');
insert into class_perk values ('artisan_deep_pot', 'artisan', 1, 26, 'Deep Pot', 'Servings +1 on every dish cooked in a pot or bowl you shape, by anyone: cheese, berry compote, pottage, porridge, apple pie, preserves, broth and stew.', '{"serve:unfired_clay_pot":1,"serve:unfired_clay_bowl":1}');
insert into class_perk values ('artisan_cut_true', 'artisan', 2, 7, 'Cut True', 'Rings, pendants and circlets you make: skill gain on each stone''s skill up to +5%, by QL: full at QL 100, half at QL 50 (base: QL has no effect). Circlet stones give 50% of it.', '{"cut:jewelled_ring":0.05,"cut:jewelled_pendant":0.05,"cut:circlet":0.05}');
insert into class_perk values ('artisan_fine_castings', 'artisan', 2, 9, 'Fine Castings', 'QL +10% on rings and pendants you forge from a casting, max 100.', '{"ql:ring":1.1,"ql:pendant":1.1}');
insert into class_perk values ('artisan_gem_eye', 'artisan', 2, 10, 'Gem Finder', 'Gem chance per Mine: 1 in 300 (base 1 in 400).', '{"gem:mine":0.0033333333333333335}');
insert into class_perk values ('artisan_focus_cutter', 'artisan', 3, 13, 'Focus Cutter', 'Focus wear per cast −25% on foci you set, any caster.', '{"thrift:focus":0.75}');
insert into class_perk values ('artisan_sealed_jar', 'artisan', 3, 27, 'Sealed Jar', 'Keeping time ×2 for food put up in a jar you shape, by anyone: preserves.', '{"keeps:unfired_clay_jar":0.5}');
insert into class_perk values ('artisan_sturdy_binding', 'artisan', 3, 35, 'Sturdy Binding', 'Study damage ×0.5 on books you bind (base 2 to 5 per action).', '{"sturdy:book":0.5,"sturdy:trade_book":0.5}');
insert into class_perk values ('artisan_bright_stone', 'artisan', 4, 4, 'Bright Stone', 'Skill gain on the stone''s skill: rings and pendants you make +15% (base +10%); each stone in a circlet you make +7.5% (base +5%).', '{"bright:jewelled_ring":1.5,"bright:jewelled_pendant":1.5,"bright:circlet":1.5}');
insert into class_perk values ('artisan_keen_focus', 'artisan', 4, 14, 'Keen Focus', 'Spell strength +10% and hold duration +10% from foci you set, any caster.', '{"force:focus":1.1}');
insert into class_perk values ('artisan_good_read', 'artisan', 4, 34, 'Good Read', 'Study skill gain +25% from books you bind, any reader.', '{"teach:book":1.25,"teach:trade_book":1.25}');
insert into class_perk values ('artisan_more_stones', 'artisan', 5, 12, 'More Stones', 'Mining can find 6 more stones, only for you: opal (taming), peridot (farming), amethyst (tailoring), jasper (pottery), onyx (masonry) and amber (cooking). Set and worn like any other stone.', '{"more_stones":1}');
insert into class_perk values ('artisan_amphora', 'artisan', 5, 46, 'Amphora', 'New pottery recipe: 4 clay make an unfired amphora; fire it in a kiln. Holds 20 of one food or drink. Rot rate when left out ×0.5. Usable by anyone.', '{"amphora":1}');
insert into class_perk values ('artisan_potters_wheel', 'artisan', 5, 49, 'Potter''s Wheel', 'New build: potter''s wheel (12 planks, 2 shafts, a stone slab and 12 nails). Pottery time −30% within 2.4 tiles, for anyone, on top of other bonuses.', '{"potters_wheel":1}');
insert into class_perk values ('artisan_glaze', 'artisan', 6, 28, 'Glaze', 'New action: Glaze it, on a clay pot, a clay bowl, a clay jar or an amphora. Cost: 1 lot of ashes. Glazed item never decays, anywhere.', '{"glaze_item":1}');
insert into class_perk values ('artisan_trade_book', 'artisan', 6, 36, 'Trade Book', 'New papyrusmaking recipe: 6 papyrus, 2 leather and 2 inks with a needle make a book on any crafting skill you have at 50+. Study teaches that skill, as much per action as a plain book teaches mind logic. Readable by anyone.', '{"trade_book":1}');
insert into class_perk values ('artisan_circlet', 'artisan', 6, 48, 'Circlet', 'New jewellery recipe: 2 gold lumps with a file make a circlet (head slot, replaces a helm). Holds 3 stones, set by anyone from the stone''s menu; each gives 50% of a ring''s bonus: +5% skill gain on its skill.', '{"circlet":1}');
insert into class_perk values ('blade_measured_cut', 'blade', 1, 1, 'Measured Cut', 'Spell. Stamina 8%. Cooldown 6 s. Blow at 130%, cannot miss. Target: enemy within reach.', '{}');
insert into class_perk values ('blade_challenge', 'blade', 1, 32, 'Challenge', 'Spell. Stamina 8%. Cooldown 15 s. Target hunts only you for 10 s.', '{}');
insert into class_perk values ('blade_light_sword', 'blade', 1, 108, 'Light Sword', 'Sword swing stamina −30%.', '{"wind:swords":0.7}');
