insert into class_perk values ('blade_guardians_call', 'blade', 6, 33, 'Guardian’s Call', 'Spell. Stamina 18%. Cooldown 45 s. Every creature within 5 tiles hunting anyone hunts only you for 8 s.', '{}');
insert into class_perk values ('blade_shield_mastery', 'blade', 6, 109, 'Shield Mastery', 'Shield block chance +8 percentage points, max 70% (base max 60%).', '{"block:shield":0.08,"blockcap:shield":0.7}');
insert into class_perk values ('berserker_wild_swing', 'berserker', 1, 18, 'Wild Swing', 'Spell. Stamina 5%. Cooldown 5 s. Blow at 140%, miss chance ×2 a swing''s.', '{}');
insert into class_perk values ('berserker_shrug_it_off', 'berserker', 1, 30, 'Shrug It Off', 'Spell. Stamina 10%. Cooldown 60 s. Worst wound: severity −50%, bleeding stopped.', '{}');
insert into class_perk values ('berserker_axe_mastery', 'berserker', 1, 101, 'Axe Mastery', 'Axe damage +10%.', '{"dmg:axes":1.1}');
