insert into class_perk values ('berserker_maul_mastery', 'berserker', 2, 106, 'Maul Mastery', 'Maul damage +10%.', '{"dmg:mauls":1.1}');
insert into class_perk values ('berserker_battle_rage', 'berserker', 3, 21, 'Battle Rage', 'Spell. Stamina 15%. Cooldown 90 s. For 15 s: damage dealt +30%, damage taken +20%.', '{}');
insert into class_perk values ('berserker_adrenaline', 'berserker', 3, 29, 'Adrenaline', 'Spell. Cooldown 2 minutes. No stamina cost. For 10 s: swings and draws cost no stamina, swing time −15%.', '{}');
insert into class_perk values ('berserker_executioner', 'berserker', 3, 125, 'Executioner', 'Damage +25% on creatures below 25% health.', '{"finish:below":0.25,"finish:dmg":1.25}');
