insert into class_perk values ('berserker_blood_price', 'berserker', 4, 20, 'Blood Price', 'Spell. Cooldown 30 s. No stamina cost; costs 10% health. Blow at 250%.', '{}');
insert into class_perk values ('berserker_pain_fuels', 'berserker', 4, 112, 'Pain Fuels', 'Damage +15% below 50% of your health, +30% below 25%.', '{"pain:below":0.5,"pain:dmg":1.15,"pain:deep":0.25,"pain:deeper":1.3}');
