insert into class_perk values ('berserker_whirlwind', 'berserker', 5, 14, 'Whirlwind', 'Spell. Stamina 25%. Cooldown 45 s. 2 blows at 90% on every enemy within 2 tiles.', '{}');
insert into class_perk values ('berserker_wild_strength', 'berserker', 5, 130, 'Wild Strength', 'Swing time −10% with a two-handed weapon.', '{"swing:two_handed":0.9}');
insert into class_perk values ('berserker_earthshaker', 'berserker', 6, 45, 'Earthshaker', 'Spell. Stamina 25%. Cooldown 60 s. Needs a maul in hand: blow at 100% on every enemy within 3 tiles; each held for 1 s.', '{}');
insert into class_perk values ('berserker_last_rage', 'berserker', 6, 50, 'Last Rage', 'Spell. Cooldown 10 minutes. No stamina cost. Only below 25% health. For 10 s: every blow landed is critical.', '{}');
insert into class_perk values ('berserker_thirst_for_blood', 'berserker', 6, 113, 'Thirst for Blood', 'Health +1% per blow landed on a creature.', '{"leech:blow":0.01}');
insert into class_perk values ('pikeman_overreach', 'pikeman', 1, 13, 'Overreach', 'Spell. Stamina 8%. Cooldown 8 s. Blow at 110% on an enemy up to 2 tiles past your reach. Your next swing delayed 1 s.', '{}');
