insert into class_perk values ('pikeman_vital_thrust', 'pikeman', 2, 5, 'Vital Thrust', 'Spell. Stamina 12%. Cooldown 20 s. Blow at 120%, critical chance ×2 a swing''s.', '{}');
insert into class_perk values ('pikeman_sweep_the_legs', 'pikeman', 2, 6, 'Sweep the Legs', 'Spell. Stamina 10%. Cooldown 15 s. Blow at 80%. Target move speed 50% for 8 s.', '{}');
insert into class_perk values ('pikeman_light_haft', 'pikeman', 2, 105, 'Light Haft', 'Polearm swing stamina −25%.', '{"wind:polearms":0.75}');
insert into class_perk values ('pikeman_rally_the_line', 'pikeman', 3, 32, 'Rally the Line', 'Spell. Stamina 15%. Cooldown 90 s. You and everyone within 5 tiles: stamina +20% of max.', '{}');
insert into class_perk values ('pikeman_hook', 'pikeman', 3, 33, 'Hook', 'Spell. Stamina 10%. Cooldown 15 s. Pull an enemy up to 4 tiles away 2 tiles towards you, min 1 tile away, over walkable ground. It turns on you.', '{}');
