insert into class_perk values ('pikeman_twin_thrust', 'pikeman', 4, 14, 'Twin Thrust', 'Spell. Stamina 14%. Cooldown 20 s. 2 blows at 70%, one after the other.', '{}');
insert into class_perk values ('pikeman_reach_advantage', 'pikeman', 4, 19, 'Reach Advantage', 'Spell. Stamina 8%. Cooldown 15 s. Blow at 150% on a creature outside its own reach of you (1.1 tiles, 6 for throwers), 100% otherwise.', '{}');
insert into class_perk values ('pikeman_bastion', 'pikeman', 4, 113, 'Bastion', 'Damage taken −15% after standing still for 1.5 s.', '{"still:taken":0.85}');
insert into class_perk values ('pikeman_skewer', 'pikeman', 5, 2, 'Skewer', 'Spell. Stamina 12%. Cooldown 15 s. Blow at 150%; blow at 60% on every enemy up to 2 tiles behind it, within 0.5 tiles of the line.', '{}');
insert into class_perk values ('pikeman_keep_away', 'pikeman', 5, 17, 'Keep Away', 'Spell. Stamina 10%. Cooldown 20 s. For 10 s: every blow you land pushes the target 1 tile away, over walkable ground.', '{}');
