insert into class_perk values ('archer_aimed_shot', 'archer', 1, 1, 'Aimed Shot', 'Spell. Stamina 8%. Cooldown 8 s. Needs a bow in hand: shot at 140%, cannot miss.', '{}');
insert into class_perk values ('archer_quick_shot', 'archer', 1, 2, 'Quick Shot', 'Spell. Stamina 6%. Cooldown 6 s. Needs a bow in hand: shot at 80%; your next draw 1 s sooner.', '{}');
insert into class_perk values ('archer_bow_mastery', 'archer', 1, 101, 'Bow Mastery', 'Shot damage +10%.', '{"dmg:archery":1.1}');
insert into class_perk values ('archer_long_shot', 'archer', 2, 9, 'Long Shot', 'Spell. Stamina 10%. Cooldown 15 s. Needs a bow in hand: shot at 110% on an enemy up to ×1.5 your bow''s range, hit chance as at near range.', '{}');
insert into class_perk values ('archer_read_the_wind', 'archer', 2, 29, 'Read the Wind', 'Spell. Stamina 6%. Cooldown 30 s. Your next shot within 30 s (draw or spell): cannot miss, critical chance ×2.', '{}');
insert into class_perk values ('archer_close_quarters', 'archer', 2, 107, 'Close Quarters', 'Min draw distance: 0.6 tiles (base 1.2).', '{"closest:draw":0.5}');
insert into class_perk values ('archer_crippling_shot', 'archer', 3, 6, 'Crippling Shot', 'Spell. Stamina 10%. Cooldown 15 s. Needs a bow in hand: shot at 80%. Target move speed 50% for 8 s.', '{}');
insert into class_perk values ('archer_point_blank', 'archer', 3, 10, 'Point Blank', 'Spell. Stamina 8%. Cooldown 10 s. Needs a bow in hand: shot at 160% on an enemy within 2 tiles, including inside min draw distance (1.2 tiles).', '{}');
