insert into class_perk values ('skirmisher_marked_for_death', 'skirmisher', 6, 49, 'Marked for Death', 'Spell. Stamina 15%. Cooldown 60 s. Enemy within 12 tiles: critical chance of players'' blows, throws and shots on it ×2 for 15 s.', '{}');
insert into class_perk values ('skirmisher_long_arm', 'skirmisher', 6, 102, 'Long Arm', 'Javelin and throwing axe reach +1 tile: throwing axe 5.2 (base 4.2), javelin 6.2 (base 5.2).', '{"length:throwing":1}');
insert into class_perk values ('chirurgeon_field_dressing', 'chirurgeon', 1, 1, 'Field Dressing', 'Spell. Stamina 6%. Cooldown 8 s. You or a player within 2 tiles: health +10%; worst bleeding wound stops bleeding.', '{}');
