insert into class_perk values ('binder_lingering_chill', 'binder', 2, 103, 'Lingering Chill', 'When your Bind or Lock ends: creature speed 70% for 5 s.', '{"chill:pace":0.7,"chill:secs":5}');
insert into class_perk values ('binder_heavy_limbs', 'binder', 3, 20, 'Heavy Limbs', 'Spell. Stamina 10%. Cooldown 20 s. Needs a sapphire or diamond focus in your pack: enemy within 8 tiles: attack rate −30% for 10 s.', '{}');
insert into class_perk values ('binder_dull_claws', 'binder', 3, 21, 'Dull Claws', 'Spell. Stamina 10%. Cooldown 20 s. Needs a sapphire or diamond focus in your pack: enemy within 8 tiles: damage of its blows on anything −30% for 10 s.', '{}');
