insert into class_perk values ('binder_brittle', 'binder', 4, 27, 'Brittle', 'Spell. Stamina 12%. Cooldown 30 s. Needs a sapphire or diamond focus in your pack: enemy within 8 tiles: damage taken +25% from blows, shots, throws, fire and shatter for 10 s.', '{}');
insert into class_perk values ('binder_brittle_hold', 'binder', 4, 105, 'Brittle Hold', 'Damage taken +20% by a creature held by your Bind or Lock, from blows, shots, throws, fire and shatter.', '{"bind:brittle":1.2}');
