insert into class_perk values ('binder_still_skin', 'binder', 5, 35, 'Still Skin', 'Spell. Stamina 12%. Cooldown 45 s. Needs a sapphire or diamond focus in your pack: damage taken from every blow −20% for 10 s.', '{}');
insert into class_perk values ('binder_hard_edges', 'binder', 5, 110, 'Hard Edges', 'Shatter damage +20%.', '{"shatter:size":1.2}');
insert into class_perk values ('binder_mass_root', 'binder', 6, 15, 'Mass Root', 'Spell. Stamina 18%. Cooldown 40 s. Needs a sapphire or diamond focus in your pack: every enemy within 4 tiles rooted for 6 s: no moving; still strikes and throws within its reach.', '{}');
