insert into class_perk values ('warder_ward', 'warder', 1, 1, 'Ward', 'Spell. Stamina 5%. Cooldown 10 s. Needs a topaz or emerald focus in your pack: skin of 40% on you. Skin of 100%: 6.5% of max health (warding 1, focus QL 1) to 35% (warding 100, focus QL 100), linear in each. Absorbs blows before shield and armour; a new skin replaces an old one only if larger.', '{}');
insert into class_perk values ('warder_ward_other', 'warder', 1, 11, 'Ward Other', 'Spell. Stamina 6%. Cooldown 10 s. Needs a topaz or emerald focus in your pack: skin of 40% on a player within 6 tiles. Skin of 100%: 6.5% of max health (warding 1, focus QL 1) to 35% (warding 100, focus QL 100), linear in each. Absorbs blows before shield and armour; a new skin replaces an old one only if larger.', '{}');
insert into class_perk values ('warder_second_wind', 'warder', 1, 115, 'Second Wind', 'Stamina +10% when a blow uses up your skin.', '{"stamina:skin":0.1}');
insert into class_perk values ('warder_greater_ward', 'warder', 2, 2, 'Greater Ward', 'Spell. Stamina 10%. Cooldown 20 s. Needs a topaz or emerald focus in your pack: skin of 100% on you. Skin of 100%: 6.5% of max health (warding 1, focus QL 1) to 35% (warding 100, focus QL 100), linear in each. Absorbs blows before shield and armour; a new skin replaces an old one only if larger.', '{}');
insert into class_perk values ('warder_thicken', 'warder', 2, 47, 'Thicken', 'Spell. Stamina 6%. Cooldown 30 s. Needs a topaz or emerald focus in your pack: your next skin within 60 s, on anyone: size +50%.', '{}');
insert into class_perk values ('warder_watchful', 'warder', 2, 125, 'Watchful', 'A creature that hits anyone within 4 tiles of you turns on you.', '{"watch:reach":4}');
insert into class_perk values ('warder_greater_ward_other', 'warder', 3, 12, 'Greater Ward Other', 'Spell. Stamina 12%. Cooldown 20 s. Needs a topaz or emerald focus in your pack: skin of 100% on a player within 6 tiles. Skin of 100%: 6.5% of max health (warding 1, focus QL 1) to 35% (warding 100, focus QL 100), linear in each. Absorbs blows before shield and armour; a new skin replaces an old one only if larger.', '{}');
insert into class_perk values ('warder_ward_link', 'warder', 3, 20, 'Ward Link', 'Spell. Stamina 15%. Cooldown 60 s. Needs a topaz or emerald focus in your pack: for 30 s: when your skin on anyone within 8 tiles is used up, a skin of 30% replaces it, once each. Skin of 100%: 6.5% of max health (warding 1, focus QL 1) to 35% (warding 100, focus QL 100), linear in each. Absorbs blows before shield and armour; a new skin replaces an old one only if larger.', '{}');
insert into class_perk values ('warder_protector', 'warder', 3, 122, 'Protector', 'Skin size on others +25%.', '{"skin:other":1.25}');
insert into class_perk values ('warder_stoneskin', 'warder', 4, 7, 'Stoneskin', 'Spell. Stamina 12%. Cooldown 45 s. Needs a topaz or emerald focus in your pack: damage taken from every blow −25% for 10 s.', '{}');
insert into class_perk values ('warder_ward_burst', 'warder', 4, 32, 'Ward Burst', 'Spell. Stamina 15%. Cooldown 30 s. Needs a topaz or emerald focus in your pack: your skin breaks; every enemy within 3 tiles takes 1 damage per hundredth of your health it held.', '{}');
insert into class_perk values ('warder_thorns', 'warder', 4, 128, 'Thorns', 'Creature that hits you takes 10% of its own attack as damage.', '{"thorns:attack":0.1}');
insert into class_perk values ('warder_deep_ward', 'warder', 5, 3, 'Deep Ward', 'Spell. Stamina 20%. Cooldown 60 s. Needs a topaz or emerald focus in your pack: skin of 200% on you. Skin of 100%: 6.5% of max health (warding 1, focus QL 1) to 35% (warding 100, focus QL 100), linear in each. Absorbs blows before shield and armour; a new skin replaces an old one only if larger.', '{}');
insert into class_perk values ('warder_sanctuary', 'warder', 5, 14, 'Sanctuary', 'Spell. Stamina 25%. Cooldown 60 s. Needs a topaz or emerald focus in your pack: skin of 80% on you and everyone within 6 tiles. Skin of 100%: 6.5% of max health (warding 1, focus QL 1) to 35% (warding 100, focus QL 100), linear in each. Absorbs blows before shield and armour; a new skin replaces an old one only if larger.', '{}');
insert into class_perk values ('warder_thick_skin', 'warder', 5, 101, 'Thick Skin', 'Skin size +20%, the school''s Aegis and Bulwark included.', '{"skin:size":1.2}');
insert into class_perk values ('warder_bastion_of_stone', 'warder', 6, 42, 'Bastion of Stone', 'Spell. Stamina 35%. Cooldown 5 minutes. Needs a topaz or emerald focus in your pack: you and everyone within 4 tiles: damage taken from every blow −40% for 10 s.', '{}');
insert into class_perk values ('warder_unbreakable', 'warder', 6, 44, 'Unbreakable', 'Spell. Stamina 45%. Cooldown 15 minutes. Needs a topaz or emerald focus in your pack: for 6 s: no blow aimed at you lands.', '{}');
insert into class_perk values ('warder_overcharge', 'warder', 6, 104, 'Overcharge', 'A skin laid over an existing one adds to it, max 150% of the larger (base: replaces a smaller one only).', '{"skin:over":1.5}');
