insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('warder_greater_ward', 'warder', 2, 'Greater Ward', 'Needs a topaz or emerald focus in your pack: skin of 100% on you. Skin of 100%: 6.5% of max health (warding 1, focus QL 1) to 35% (warding 100, focus QL 100), linear in each. Absorbs blows before shield and armour; a new skin replaces an old one only if larger.', 0.1, 20, array['self']::text[], '{"skin":1}', 'warding');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('warder_thicken', 'warder', 47, 'Thicken', 'Needs a topaz or emerald focus in your pack: your next skin within 60 s, on anyone: size +50%.', 0.06, 30, array['self']::text[], '{"more":1.5,"secs":60}', 'warding');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('warder_greater_ward_other', 'warder', 12, 'Greater Ward Other', 'Needs a topaz or emerald focus in your pack: skin of 100% on a player within 6 tiles. Skin of 100%: 6.5% of max health (warding 1, focus QL 1) to 35% (warding 100, focus QL 100), linear in each. Absorbs blows before shield and armour; a new skin replaces an old one only if larger.', 0.12, 20, array['player']::text[], '{"skin":1,"reach":6}', 'warding');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('warder_ward_link', 'warder', 20, 'Ward Link', 'Needs a topaz or emerald focus in your pack: for 30 s: when your skin on anyone within 8 tiles is used up, a skin of 30% replaces it, once each. Skin of 100%: 6.5% of max health (warding 1, focus QL 1) to 35% (warding 100, focus QL 100), linear in each. Absorbs blows before shield and armour; a new skin replaces an old one only if larger.', 0.15, 60, array['self']::text[], '{"secs":30,"reach":8,"skin":0.3}', 'warding');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('warder_stoneskin', 'warder', 7, 'Stoneskin', 'Needs a topaz or emerald focus in your pack: damage taken from every blow −25% for 10 s.', 0.12, 45, array['self']::text[], '{"cut":0.25,"secs":10}', 'warding');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('warder_ward_burst', 'warder', 32, 'Ward Burst', 'Needs a topaz or emerald focus in your pack: your skin breaks; every enemy within 3 tiles takes 1 damage per hundredth of your health it held.', 0.15, 30, array['self']::text[], '{"reach":3,"dmg":1}', 'warding');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('warder_deep_ward', 'warder', 3, 'Deep Ward', 'Needs a topaz or emerald focus in your pack: skin of 200% on you. Skin of 100%: 6.5% of max health (warding 1, focus QL 1) to 35% (warding 100, focus QL 100), linear in each. Absorbs blows before shield and armour; a new skin replaces an old one only if larger.', 0.2, 60, array['self']::text[], '{"skin":2}', 'warding');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('warder_sanctuary', 'warder', 14, 'Sanctuary', 'Needs a topaz or emerald focus in your pack: skin of 80% on you and everyone within 6 tiles. Skin of 100%: 6.5% of max health (warding 1, focus QL 1) to 35% (warding 100, focus QL 100), linear in each. Absorbs blows before shield and armour; a new skin replaces an old one only if larger.', 0.25, 60, array['self']::text[], '{"skin":0.8,"reach":6}', 'warding');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('warder_bastion_of_stone', 'warder', 42, 'Bastion of Stone', 'Needs a topaz or emerald focus in your pack: you and everyone within 4 tiles: damage taken from every blow −40% for 10 s.', 0.35, 300, array['self']::text[], '{"cut":0.4,"secs":10,"reach":4}', 'warding');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('warder_unbreakable', 'warder', 44, 'Unbreakable', 'Needs a topaz or emerald focus in your pack: for 6 s: no blow aimed at you lands.', 0.45, 900, array['self']::text[], '{"secs":6}', 'warding');
