create or replace function weapon_reach(p_def text) returns double precision language sql immutable as $fn$ select case p_def when 'hunting_knife' then 2.2 when 'butchering_knife' then 2.2 when 'carving_knife' then 2.2 when 'short_sword' then 2.6 when 'sword' then 2.6 when 'long_sword' then 2.6 when 'hatchet' then 2.4 when 'battle_axe' then 2.4 when 'club' then 2.4 when 'maul' then 2.4 when 'spear' then 3.6 when 'javelin' then 5.2 when 'throwing_axe' then 4.2 end::double precision $fn$;
