create or replace function enchant_on(p_id text) returns text language sql immutable as $fn$ select case p_id when 'emberbrand' then 'melee' when 'razoredge' then 'melee' when 'concussion' then 'melee' when 'venomfang' then 'melee' when 'gale' then 'melee' when 'nightblade' then 'melee' when 'sunstrike' then 'melee' when 'leeching' then 'melee' when 'tidecaller' then 'melee' when 'farsight' then 'bow' when 'flamearrow' then 'bow' when 'frostbite' then 'bow' when 'stoneskin' then 'armour' when 'emberward' then 'armour' when 'featherstep' then 'boots' when 'thornhide' then 'armour' when 'shadowcloak' then 'chest' when 'bulwark' then 'shield' when 'swiftwork' then 'tool' when 'truesteel' then 'tool' when 'bountiful' then 'reaper' when 'lodestone' then 'pick' when 'lanterns_grace' then 'light' when 'scholars_band' then 'ring' when 'knackstone' then 'ring' when 'steady_heart' then 'amulet' when 'hearthbound' then 'amulet' when 'favoured' then 'amulet' when 'stillwater' then 'amulet' when 'packmule' then 'pack' when 'seals_coat' then 'chest' when 'hawks_eye' then 'head' when 'ember_heart' then 'furnace' when 'masterwork' then 'station' when 'fair_wind' then 'ship' when 'deep_hold' then 'hull' when 'true_axle' then 'cart' when 'bag_of_holding' then 'store' when 'snarecraft' then 'trap' when 'netmender' then 'net' when 'dreamweave' then 'bed' when 'fleetfoot' then 'saddle' when 'tamers_bridle' then 'bridle' end $fn$;
create or replace function enchant_fits(p_on text, p_def text) returns boolean language sql immutable as $fn$ select case p_on when 'melee' then p_def = any (array['hunting_knife', 'butchering_knife', 'carving_knife', 'short_sword', 'sword', 'long_sword', 'hatchet', 'battle_axe', 'club', 'maul', 'spear']::text[]) when 'bow' then p_def = any (array['short_bow', 'medium_bow', 'long_bow', 'composite_bow']::text[]) when 'armour' then p_def = any (array['wool_cap', 'cloth_tunic', 'cloth_sleeves', 'cloth_trousers', 'cloth_shoes', 'leather_cap', 'leather_jerkin', 'leather_sleeves', 'leather_trousers', 'leather_boots', 'chain_coif', 'chain_hauberk', 'chain_sleeves', 'chain_leggings', 'chain_boots', 'helm', 'plate_breastplate', 'plate_arms', 'plate_legs', 'plate_boots', 'scale_helm', 'scale_cuirass', 'scale_sleeves', 'scale_leggings', 'scale_boots']::text[]) when 'boots' then p_def = any (array['cloth_shoes', 'leather_boots', 'chain_boots', 'plate_boots', 'scale_boots']::text[]) when 'chest' then p_def = any (array['cloth_tunic', 'leather_jerkin', 'chain_hauberk', 'plate_breastplate', 'scale_cuirass']::text[]) when 'shield' then p_def = any (array['wooden_shield', 'metal_shield']::text[]) when 'tool' then p_def = any (array['awl', 'brush', 'butchering_knife', 'carving_knife', 'chisel', 'clay_bowl', 'clay_jar', 'clay_pot', 'file', 'fishing_net', 'fishing_rod', 'frying_pan', 'hammer', 'hatchet', 'mallet', 'needle', 'pickaxe', 'quern', 'rake', 'rope_tool', 'saw', 'shovel', 'sickle', 'trowel']::text[]) when 'reaper' then p_def = any (array['sickle', 'fishing_rod']::text[]) when 'pick' then p_def = any (array['pickaxe']::text[]) when 'light' then p_def = any (array['lantern', 'torch']::text[]) when 'ring' then p_def = any (array['jewelled_ring']::text[]) when 'pack' then p_def = any (array['backpack', 'satchel']::text[]) when 'head' then p_def = any (array['wool_cap', 'leather_cap', 'chain_coif', 'helm', 'scale_helm']::text[]) when 'amulet' then p_def = any (array['jewelled_pendant']::text[]) when 'furnace' then p_def = any (array['smelter', 'kiln']::text[]) when 'station' then p_def = any (array['anvil', 'loom']::text[]) when 'ship' then p_def = any (array['sailing_boat', 'caravel']::text[]) when 'hull' then p_def = any (array['rowing_boat', 'sailing_boat', 'caravel']::text[]) when 'cart' then p_def = any (array['cart', 'large_cart', 'wagon']::text[]) when 'store' then p_def = any (array['desk', 'chest', 'coffer', 'cupboard', 'wardrobe', 'shelves', 'bookshelf', 'larder', 'barrel', 'stall', 'mailbox', 'firewood_rack', 'bulk_bin', 'craft_bin', 'seed_bin', 'sprout_bin', 'trash_crate', 'cart', 'large_cart', 'wagon', 'rowing_boat', 'sailing_boat', 'caravel', 'small_barrel', 'large_barrel', 'crate_log', 'crate_plank', 'amphora', 'bottle', 'sack', 'satchel', 'backpack']::text[]) when 'trap' then p_def = any (array['snare', 'creel', 'deadfall']::text[]) when 'net' then p_def = any (array['fishing_net']::text[]) when 'bed' then p_def = any (array['bed', 'cot', 'tent']::text[]) when 'saddle' then p_def = any (array['saddle']::text[]) when 'bridle' then p_def = any (array['bridle']::text[]) else false end $fn$;
create or replace function enchant_wrong_kind(p_id text) returns text language sql immutable as $fn$ select case p_id when 'emberbrand' then 'Emberbrand: only on melee weapons (not bows or thrown weapons).' when 'razoredge' then 'Razoredge: only on melee weapons (not bows or thrown weapons).' when 'concussion' then 'Concussion: only on melee weapons (not bows or thrown weapons).' when 'venomfang' then 'Venomfang: only on melee weapons (not bows or thrown weapons).' when 'gale' then 'Gale: only on melee weapons (not bows or thrown weapons).' when 'nightblade' then 'Nightblade: only on melee weapons (not bows or thrown weapons).' when 'sunstrike' then 'Sunstrike: only on melee weapons (not bows or thrown weapons).' when 'leeching' then 'Leeching: only on melee weapons (not bows or thrown weapons).' when 'tidecaller' then 'Tidecaller: only on melee weapons (not bows or thrown weapons).' when 'farsight' then 'Farsight: only on bows.' when 'flamearrow' then 'Flamearrow: only on bows.' when 'frostbite' then 'Frostbite: only on bows.' when 'stoneskin' then 'Stoneskin: only on worn armour or clothing.' when 'emberward' then 'Emberward: only on worn armour or clothing.' when 'featherstep' then 'Featherstep: only on boots or shoes.' when 'thornhide' then 'Thornhide: only on worn armour or clothing.' when 'shadowcloak' then 'Shadowcloak: only on chest pieces: tunic, jerkin, hauberk, breastplate or cuirass.' when 'bulwark' then 'Bulwark: only on shields.' when 'swiftwork' then 'Swiftwork: only on tools used for an action.' when 'truesteel' then 'Truesteel: only on tools used for an action.' when 'bountiful' then 'Bountiful: only on sickles or fishing rods.' when 'lodestone' then 'Lodestone: only on pickaxes.' when 'lanterns_grace' then 'Lantern''s Grace: only on lanterns or torches.' when 'scholars_band' then 'Scholar''s Band: only on jewelled rings.' when 'knackstone' then 'Knackstone: only on jewelled rings.' when 'steady_heart' then 'Steady Heart: only on jewelled pendants.' when 'hearthbound' then 'Hearthbound: only on jewelled pendants.' when 'favoured' then 'Favoured: only on jewelled pendants.' when 'stillwater' then 'Stillwater: only on jewelled pendants.' when 'packmule' then 'Packmule: only on backpacks or satchels.' when 'seals_coat' then 'Seal''s Coat: only on chest pieces: tunic, jerkin, hauberk, breastplate or cuirass.' when 'hawks_eye' then 'Hawk''s Eye: only on headwear: cap, coif or helm.' when 'ember_heart' then 'Ember Heart: only on smelters or kilns.' when 'masterwork' then 'Masterwork: only on anvils or looms.' when 'fair_wind' then 'Fair Wind: only on sailing boats or caravels.' when 'deep_hold' then 'Deep Hold: only on boats: rowing boat, sailing boat or caravel.' when 'true_axle' then 'True Axle: only on carts, large carts or wagons.' when 'bag_of_holding' then 'Bag of Holding: only on containers: chest, barrel, larder, crate, bag, pack, cart, wagon or boat.' when 'snarecraft' then 'Snarecraft: only on traps: snare, deadfall or creel.' when 'netmender' then 'Netmender: only on fishing nets.' when 'dreamweave' then 'Dreamweave: only on beds, cots or tents.' when 'fleetfoot' then 'Fleetfoot: only on saddles.' when 'tamers_bridle' then 'Tamer''s Bridle: only on bridles.' end $fn$;
