create or replace function enchant_unit(p_effect text) returns text language sql immutable as $fn$ select case p_effect when 'mule' then 'kg' when 'master' then 'QL' end $fn$;
create or replace function worn_cap(p_effect text) returns double precision language sql immutable as $fn$ select case p_effect when 'guard' then 0.15::double precision when 'fireguard' then 0.5::double precision when 'thorns' then 0.25::double precision end $fn$;
create or replace function enchant_line(p_id text) returns text language sql immutable as $fn$ select case p_id when 'emberbrand' then 'Burn on {v} of hits. Burn: 1% of max health per second for 8 s, never the last of it.' when 'razoredge' then 'Bleed on {v} of hits. Bleed: 15% of the blow per second for 6 s, never the last of it (as a knife).' when 'concussion' then 'Stun (2 s) on {v} of hits. Stunned: no moving or striking; a new stun restarts it, does not add.' when 'venomfang' then 'Venom on {v} of hits. Venom: 1% of max health per second for 8 s, never the last of it (as a venomous bite).' when 'gale' then 'Swing time −{v}.' when 'nightblade' then 'Critical chance +{v} (added).' when 'sunstrike' then 'Damage +{v} on hostile (untameable) monsters.' when 'leeching' then 'Health back: {v} of damage dealt, on hits that leave the target standing; each point 1.2% of your health, as a creature''s blow.' when 'tidecaller' then 'Per hit: target''s next blow delayed {v} of its attack interval.' when 'farsight' then 'Range +{v}.' when 'flamearrow' then 'Shot: burn on {v} of hits. Burn: 1% of max health per second for 8 s, never the last of it.' when 'frostbite' then 'Shot: slow to 70% speed for 3 s on {v} of hits; a new slow restarts it, does not add.' when 'stoneskin' then 'Worn: damage taken from blows −{v}; pieces add, max 15%.' when 'emberward' then 'Worn: burn damage taken −{v}; pieces add, max 50%.' when 'featherstep' then 'Worn: walk speed +{v}.' when 'thornhide' then 'Worn: an attacker that hits you takes {v} of the damage it dealt, as your blow would; pieces add, max 25%.' when 'shadowcloak' then 'Worn: at night, creature notice range −{v}.' when 'bulwark' then 'Shield block chance +{v}, above the normal shield max.' when 'swiftwork' then 'Action time −{v}.' when 'truesteel' then 'Damage from use −{v}.' when 'bountiful' then 'Sickle bush harvest or rod catch: one extra on {v} of actions.' when 'lodestone' then 'Mining ore or stone: one extra on {v} of actions.' when 'lanterns_grace' then 'Candle or struck torch burn time +{v}; light radius +2 tiles.' when 'scholars_band' then 'Worn: skill gain +{v}.' when 'knackstone' then 'Worn: knack chance per action +{v}.' when 'steady_heart' then 'Worn: stamina regeneration +{v}.' when 'hearthbound' then 'Worn: hunger and thirst rate −{v}.' when 'favoured' then 'Worn: favour per prayer +{v}.' when 'stillwater' then 'Worn: Calm per sitting +{v}.' when 'packmule' then 'Carried: carry weight +{v}; each pack adds its own.' when 'seals_coat' then 'Worn: swim speed +{v} (max walk speed), swimming stamina −{v}.' when 'hawks_eye' then 'Worn: sight range +{v}.' when 'ember_heart' then 'Fuel use −{v}.' when 'masterwork' then 'QL of things made here +{v}, max QL 100; the best within reach counts.' when 'fair_wind' then 'Sailing speed +{v}, on every point of sail.' when 'deep_hold' then 'Capacity +{v} (things or kg).' when 'true_axle' then 'Capacity +{v} (things or kg).' when 'bag_of_holding' then 'Capacity +{v} (things, kg or litres); contents weigh the same.' when 'snarecraft' then 'Catch chance +{v}, max 90%; creel fish chance +{v}.' when 'netmender' then 'Fish per drag +{v} on average; wear −{w}.' when 'dreamweave' then 'Rest banked per night +{v}; max banked rest +{v}.' when 'fleetfoot' then 'Mount speed +{v}, after tack makers'' bonuses.' when 'tamers_bridle' then 'In pack: tame chance per offering +{v}. On a mount: never breaks off a fight for distance.' end $fn$;
