create or replace function enchant_said(p_key text) returns text language sql immutable as $fn$ select case p_key when 'scroll' then 'Choose an enchantment scroll.' when 'weapon' then 'Choose a thing in your pack to enchant.' when 'broken' then 'Broken.' when 'gone' then 'Gone.' when 'reach' then 'Too far.' when 'plinth' then 'Need an enchanter''s plinth.' end $fn$;
create or replace function enchant_head(p_effect text) returns text language sql immutable as $fn$ select case p_effect when 'burn' then 'Burn' when 'bleed' then 'Bleed' when 'stun' then 'Stun (2 s)' when 'venom' then 'Venom' end $fn$;
create or replace function enchant_tail(p_effect text) returns text language sql immutable as $fn$ select case p_effect when 'burn' then 'Burn: 1% of max health per second for 8 s, never the last of it.' when 'bleed' then 'Bleed: 15% of the blow per second for 6 s, never the last of it (as a knife).' when 'stun' then 'Stunned: no moving or striking; a new stun restarts it, does not add.' when 'venom' then 'Venom: 1% of max health per second for 8 s, never the last of it (as a venomous bite).' end $fn$;
create or replace function enchant_hit_said(p_effect text) returns text language sql immutable as $fn$ select case p_effect when 'burn' then '{t} burning.' when 'bleed' then '{t} bleeding.' when 'stun' then '{t} stunned 2 s.' when 'venom' then '{t} envenomed.' when 'flame' then '{t} burning.' when 'frost' then '{t} slowed to 70% speed for 3 s.' end $fn$;
create or replace function scroll_harm_said(p_harm text) returns text language sql immutable as $fn$ select case p_harm when 'harmed' then 'Papyrus: 25 damage.' when 'used' then 'Papyrus: 25 damage, used up.' when 'none' then '' end $fn$;
