create or replace function fruiting_seasons(p_item text) returns text[] language sql immutable as $fn$ select case p_item when 'cherry' then array['summer']::text[] when 'apricot' then array['summer']::text[] when 'peach' then array['summer']::text[] when 'plum' then array['summer']::text[] when 'fig' then array['summer', 'autumn']::text[] when 'apple' then array['autumn']::text[] when 'pear' then array['autumn']::text[] when 'quince' then array['autumn']::text[] when 'pomegranate' then array['autumn']::text[] when 'olive' then array['autumn', 'winter']::text[] when 'lemon' then array['spring', 'winter']::text[] when 'grape' then array['autumn']::text[] when 'rose_petals' then array['spring', 'summer']::text[] when 'lavender' then array['spring', 'summer']::text[] when 'strawberry' then array['summer']::text[] when 'raspberry' then array['summer']::text[] when 'blueberry' then array['summer', 'autumn']::text[] when 'lingonberry' then array['autumn']::text[] when 'acorn' then array['autumn']::text[] when 'nuts' then array['autumn']::text[] when 'basil' then array['summer']::text[] when 'sage' then array['spring', 'summer', 'autumn']::text[] when 'thyme' then array['spring', 'summer', 'autumn']::text[] when 'mint' then array['spring', 'summer', 'autumn']::text[] end $fn$;
