create or replace function memorial_said(p_key text) returns text language sql immutable as $fn$ select case p_key when 'notYours' then 'Only whoever set this stone down, or a citizen of its settlement, may engrave it.' when 'noChisel' then 'Need a stone chisel.' when 'nothing' then 'Text is empty.' when 'same' then 'Already reads that.' end $fn$;
create or replace function memorial_says(p_text text) returns text language sql immutable as $fn$ select case when coalesce(p_text, '') = '' then 'Memorial stone: blank. Engrave it with a stone chisel, up to 72 characters.' else 'Memorial stone: “' || p_text || '”' end $fn$;
create or replace function engraved_said(p_text text, p_recut boolean) returns text language sql immutable as $fn$ select case when p_recut then 'Re-engraved: “' || p_text || '”.' else 'Engraved: “' || p_text || '”.' end $fn$;
