create or replace function sign_said(p_key text) returns text language sql immutable as $fn$ select case p_key when 'notMade' then 'Only single items made at QL 90 or better carry a maker''s name to sign; not piles or furniture.' when 'signed' then 'Already signed: once only.' when 'nothing' then 'Signature is empty.' end $fn$;
create or replace function sign_not_yours_said(p_who text) returns text language sql immutable as $fn$ select 'Made by ' || p_who || ': only ' || p_who || ' may sign it.' $fn$;
create or replace function signed_said(p_text text) returns text language sql immutable as $fn$ select 'Signed: “' || p_text || '”.' $fn$;
create or replace function maker_says(p_maker text, p_signed text) returns text language sql immutable as $fn$ select case when coalesce(p_maker, '') = '' then '' when coalesce(p_signed, '') = '' then ' Made by ' || p_maker || '.' else ' Made by ' || p_maker || ', signed: “' || p_signed || '”.' end $fn$;
