create or replace function vine_said(p_key text) returns text language sql immutable as $fn$ select case p_key when 'none' then 'No vine: plant a grape cutting at its foot.' when 'young' then 'Too young: a vine bears from 3 days after planting.' when 'picked' then 'Already picked: bears again 1 day after picking.' when 'has' then 'Already has a vine.' when 'soil' then 'Vines need soil: set the trellis on grass, dirt, field, lawn or steppe.' when 'noCutting' then 'Need a grape cutting.' when 'noWild' then 'No wild vine in this.' when 'cut' then 'Cutting already taken from this thorn bush.' when 'noTool' then 'Need a sickle.' when 'wall' then 'Trellis: ground level, outside a building, against the outer face of a finished solid wall or window.' when 'turn' then 'No other side of this tile has the outer face of a finished solid wall or window.' when 'upstairs' then 'Trellis: ground level only, not upstairs.' when 'inside' then 'Inside a building.' when 'noWall' then 'No wall on that side.' when 'unfinished' then 'Wall not finished.' end $fn$;
create or replace function trellis_against_said(p_type text) returns text language sql immutable as $fn$ select case p_type when 'solid' then 'Trellis: not against a solid wall.' when 'window' then 'Trellis: not against a window.' when 'bay' then 'Trellis: not against a bay window.' when 'door' then 'Trellis: not against a door.' when 'double_door' then 'Trellis: not against a double door.' when 'arch' then 'Trellis: not against an arch.' when 'fence' then 'Trellis: not against a fence.' when 'fence_gate' then 'Trellis: not against a fence gate.' when 'iron_gate' then 'Trellis: not against an iron-bound gate.' when 'half_wall' then 'Trellis: not against a half wall.' when 'counter' then 'Trellis: not against a shop counter.' when 'railing' then 'Trellis: not against a railing.' when 'portcullis' then 'Trellis: not against a portcullis.' when 'hidden_door' then 'Trellis: not against a hidden door.' when 'rune_gate' then 'Trellis: not against a rune gate.' end $fn$;
create or replace function trellis_returned_said(p_x int, p_y int, p_vine boolean) returns text language sql immutable as $fn$ select case when p_vine then 'Returned to your pack: trellis at ' || p_x || ', ' || p_y || ', its vine as a grape cutting. A trellis needs the whole row of spots along its side of the tile; another trellis or piece now stands in that row.' else 'Returned to your pack: trellis at ' || p_x || ', ' || p_y || '. A trellis needs the whole row of spots along its side of the tile; another trellis or piece now stands in that row.' end $fn$;
create or replace function vine_season_words(p_season text, p_wait text) returns text language sql immutable as $fn$ select 'Grapes ripen in autumn only. Now: ' || p_season || '; fruits in ' || p_wait || '.' $fn$;
