create or replace function settle_said(p_key text) returns text language sql immutable as $fn$ select case p_key when 'gone' then 'Settlement gone.' when 'stranger' then 'Not a citizen of {deed}.' when 'empty' then 'Notice is empty.' when 'long' then 'Notice: max 200 characters.' when 'noNotice' then 'Notice gone.' when 'heard' then 'Notice at {deed} from {who}:' when 'what' then 'No such item.' when 'unstored' then '{what} cannot go in a settlement crate, so cannot be asked for.' when 'count' then 'Count: 1 to 1000.' when 'ql' then 'Lowest QL: whole number, max 100.' when 'full' then '{deed}: max 8 works open.' when 'noWork' then 'Work finished or taken down.' when 'far' then 'Deliver within 3 tiles of the {deed} totem.' when 'none' then 'No {what} carried.' when 'poor' then 'No {what} of QL {n} or better carried.' when 'noCrate' then '{deed} has no settlement crate to deliver into.' when 'crateFull' then 'Settlement crate at {deed} is full.' when 'delivered' then 'Delivered: {n} × {what} to {deed}.' when 'deliveredBy' then '{who} delivers {n} × {what} to {deed}.' when 'finished' then 'Work done: {n} × {what} at {deed}.' end $fn$;
